UPDATE `trans_words` SET `content_loc7`=' Hey! Where\'s the dock?! Someone stole the dock and the oil refinery from our town-in-a-box! Who would do such a thing? Where\'s the Trade Prince?' WHERE `word_id` = 173651; -- locales_quest - offerrewardtext : entry=14245
