UPDATE `trans_words` SET `content_loc7`='... thank you. I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood.' WHERE `word_id` = 131307; -- locales_quest - offerrewardtext : entry=277
UPDATE `trans_words` SET `content_loc7`='...$R? Here? I must be mad...' WHERE `word_id` = 179544; -- locales_quest - offerrewardtext : entry=26000
UPDATE `trans_words` SET `content_loc7`='...and I thought ogres smelled foul enough to begin with.$B$BWhen you bring me Mug\'Thol\'s head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady\'s wishes.' WHERE `word_id` = 132364; -- locales_quest - offerrewardtext : entry=519
UPDATE `trans_words` SET `content_loc7`='...and that makes 15 of them. Justice had a name today... and that name was Maximillian of Northshire. For Doloria!' WHERE `word_id` = 175319; -- locales_quest - offerrewardtext : entry=24704
