UPDATE `trans_words` SET `content_loc7`='Argent Soldiers told to report back to the sergeant' WHERE `word_id` = 159957; -- locales_quest - ObjectiveText1 : entry=12504
UPDATE `trans_words` SET `content_loc7`='Argent Valiant defeated' WHERE `word_id` = 164075; -- locales_quest - ObjectiveText1 : entry=13679
UPDATE `trans_words` SET `content_loc7`='Argh!  Get back!  Oh, you\'re not Scourge, are you? Thank the Banshee Queen that you\'re here. I\'ve greatly underestimated how bad it\'s gotten up here.' WHERE `word_id` = 176082; -- locales_quest - offerrewardtext : entry=25031
UPDATE `trans_words` SET `content_loc7`='Argus Highbeacon... that old guy on the top of the tower?  Great! A man his age must have been in the Argent Crusade for a long time. Maybe he can put in the good word for us at Light\'s Hope.' WHERE `word_id` = 184312; -- locales_quest - offerrewardtext : entry=27381
UPDATE `trans_words` SET `content_loc7`='Aright, mister, I got a hot deal for ya.$B$BI\'m lookin\' to offload some of these here Imperial plate armor recipes and need someone willing to take on the burden. All I want in exchange is some thorium bars. Sound good?' WHERE `word_id` = 142322; -- locales_quest - offerrewardtext : entry=7652
UPDATE `trans_words` SET `content_loc7`='Arikara defeated' WHERE `word_id` = 184118; -- locales_quest - ObjectiveText1 : entry=27329
UPDATE `trans_words` SET `content_loc7`='Ariok said he needs supplies?  I\'ve got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they\'re not letting me back in.$B$B<Gorzeeki sizes you up.>$B$BYou might be able to get in, though. Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb. I\'m pretty sure that\'s what he wants.$B$BOh, and if you happen to accidentally kill any of those orcs while you\'re up there, I wouldn\'t be terribly upset.' WHERE `word_id` = 188198; -- locales_quest - details : entry=28423
UPDATE `trans_words` SET `content_loc7`='Arm 3 Dragonmaw Workers or Merchants, then slay 10 Dragonmaw Enforcers and 4 Dragonmaw Warlocks.' WHERE `word_id` = 181731; -- locales_quest - objectives : entry=26621
UPDATE `trans_words` SET `content_loc7`='Arm 6 Frazzlecraz Explosives in the Frazzlecraz Motherlode mine.' WHERE `word_id` = 176632; -- locales_quest - objectives : entry=25183
UPDATE `trans_words` SET `content_loc7`='Arm 8 Krom\'gar "Elf Killers."' WHERE `word_id` = 179540; -- locales_quest - objectives : entry=25999
UPDATE `trans_words` SET `content_loc7`='Arm the three Explosive Charges located around the base of the southern-most tower at Talrendis Point.' WHERE `word_id` = 174479; -- locales_quest - objectives : entry=14476
UPDATE `trans_words` SET `content_loc7`='Armand Cromwell in Undercity wants you to bring him 8 Giant Flesh-Eating Tadpoles.' WHERE `word_id` = 190215; -- locales_quest - objectives : entry=29319
UPDATE `trans_words` SET `content_loc7`='Armand Cromwell wants you to fish up a Severed Abomination Head in Undercity for Master Apothecary Faranell.' WHERE `word_id` = 190205; -- locales_quest - objectives : entry=29317
UPDATE `trans_words` SET `content_loc7`='Armor plate investigated' WHERE `word_id` = 162068; -- locales_quest - ObjectiveText1 : entry=12980
UPDATE `trans_words` SET `content_loc7`='Armory sealed' WHERE `word_id` = 181279; -- locales_quest - ObjectiveText1 : entry=26501
UPDATE `trans_words` SET `content_loc7`='Arngrim\'s spirit fed' WHERE `word_id` = 162325; -- locales_quest - ObjectiveText1 : entry=13046
UPDATE `trans_words` SET `content_loc7`='Arnold and I have been fishing in and around Stormwind for years now. That\'s the kind of time it takes to find a good fishing spot. One of my favorites is called Thunder Falls.$B$BIt\'s just south of Stormwind in Elwynn Forest. Best part about Thunder Falls is the violet perch. I have never seen them anywhere else, only up there at the falls. It\'s a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?' WHERE `word_id` = 181402; -- locales_quest - details : entry=26536
UPDATE `trans_words` SET `content_loc7`='Arnold and I used to relax down at the moat in the Valley of Heroes. One day, I lost my locket in the lake and I have never been able to find it. Rumor has it that huge royal monkfish live in that moat and that they eat anything!  I know its a long shot, but do you think you could catch a few monkfish and look for my locket?$B$BPlease let me know right away if you find it, it\'s very precious to me.' WHERE `word_id` = 181229; -- locales_quest - details : entry=26488
UPDATE `trans_words` SET `content_loc7`='Aros\'s body appears to be lifeless yet still warm. Perhaps his killers are nearby.' WHERE `word_id` = 172736; -- locales_quest - offerrewardtext : entry=13895
UPDATE `trans_words` SET `content_loc7`='Arr Me Hearty! Gaining one Trinket be not enough to make ye master of the Arena! Now tis the time to truly prove your steel.' WHERE `word_id` = 142502; -- locales_quest - offerrewardtext : entry=7810
UPDATE `trans_words` SET `content_loc7`='Arranging for your flight wasn\'t cheap. Let\'s hope you have what it takes to get the job done.' WHERE `word_id` = 150028; -- locales_quest - offerrewardtext : entry=10194
UPDATE `trans_words` SET `content_loc7`='Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.$B$BThe resulting combination is now yours.' WHERE `word_id` = 139088; -- locales_quest - offerrewardtext : entry=24724
UPDATE `trans_words` SET `content_loc7`='Arrest Ambassador Slaghammer and bring him to the High Seat' WHERE `word_id` = 179970; -- locales_quest - EndText : entry=26118
UPDATE `trans_words` SET `content_loc7`='Arrested Cultists brought to Ring of Valor' WHERE `word_id` = 171993; -- locales_quest - ObjectiveText2 : entry=27802
UPDATE `trans_words` SET `content_loc7`='Arrested Cultists brought to the Stockade' WHERE `word_id` = 171960; -- locales_quest - ObjectiveText2 : entry=27749
UPDATE `trans_words` SET `content_loc7`='Arright, $Gladdie:lassie; here we go.$B$BYou just need to sneak up on one \'a them naga while they ain\'t lookin\' and use this bridle on \'em.$B$BDon\'t get too close, now! Ya gotta surprise \'em.$B$BDo it right an\' get \'em under your control, and it\'ll be time ta show \'em who\'s boss!$B$BJust keep yankin\' the reins \'til their will is broken, and you\'ll have yerself a fancy ride!$B$BGo on, now. Go git you one! I think I can see one just north \'a here...' WHERE `word_id` = 177501; -- locales_quest - details : entry=25455
UPDATE `trans_words` SET `content_loc7`='Arrite, then.$B$BLet\'s deposit these discs and be done with this!' WHERE `word_id` = 189199; -- locales_quest - offerrewardtext : entry=28753
UPDATE `trans_words` SET `content_loc7`='Arrive at Blackrock Caverns.' WHERE `word_id` = 189128; -- locales_quest - EndText : entry=28732
UPDATE `trans_words` SET `content_loc7`='Arrived at Hardwrench Hideaway' WHERE `word_id` = 190160; -- locales_quest - ObjectiveText1 : entry=29236
UPDATE `trans_words` SET `content_loc7`='Arrived at the Digsite' WHERE `word_id` = 189912; -- locales_quest - ObjectiveText1 : entry=29133
UPDATE `trans_words` SET `content_loc7`='ARRR! You might make it as an overseer after all. That oversized lizard has been the bane of many an orc!$B$B<Chief Overseer Mudlump begins to fashion the weapon>.' WHERE `word_id` = 153465; -- locales_quest - offerrewardtext : entry=11054
UPDATE `trans_words` SET `content_loc7`='Arrr, me\'n\'me crew pilfered that thar shield! We be tryin\' to get her back from that no good, landlubbin\' scallywag, Sorlof! Ye come to help, arrr?$B$BWell, as ye can see we be runnin\' a skeleton crew!$B$B<Captain Ellis laughs.>$B$BSister Mercy be needin\' another powder monkey to man the big\'uns o\'er on the poop deck. Think ye be up to the job, me hearty?$B$BHelp me crew take Sorlof down and we\'ll split the booty! Ye can have the shield, me\'n\'me crew gets the rest!' WHERE `word_id` = 156803; -- locales_quest - offerrewardtext : entry=11519
UPDATE `trans_words` SET `content_loc7`='Arthas defeated' WHERE `word_id` = 187384; -- locales_quest - EndText : entry=28218
UPDATE `trans_words` SET `content_loc7`='Arthas... He strikes recklessly - without care or caution. We have caught him off guard.$B$B<Highlord Tirion Fordring pauses, lost in thought for a moment.>$B$BWe will bolster our defenses and weather the storm.$B$BHow good are you with a cannon, $N?' WHERE `word_id` = 162318; -- locales_quest - offerrewardtext : entry=13045
UPDATE `trans_words` SET `content_loc7`='Artifact information extracted' WHERE `word_id` = 185524; -- locales_quest - ObjectiveText1 : entry=27719
UPDATE `trans_words` SET `content_loc7`='Artifact of the Broken Tablet Inspected' WHERE `word_id` = 172446; -- locales_quest - ObjectiveText1 : entry=13650
UPDATE `trans_words` SET `content_loc7`='Artifact of the Upturned Giant Inspected' WHERE `word_id` = 172447; -- locales_quest - ObjectiveText2 : entry=13650
UPDATE `trans_words` SET `content_loc7`='Artillery Shell Sabotaged' WHERE `word_id` = 175424; -- locales_quest - ObjectiveText1 : entry=24747
UPDATE `trans_words` SET `content_loc7`='As a Disciple of Naralex, I commend your bravery, $N.$B$BYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.$B$BThank you and may you prosper.' WHERE `word_id` = 135790; -- locales_quest - offerrewardtext : entry=1487
UPDATE `trans_words` SET `content_loc7`='As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures.' WHERE `word_id` = 271933; -- locales_quest - offerrewardtext : entry=8271
UPDATE `trans_words` SET `content_loc7`='As a mage, you will learn a variety of spells as your understanding grows. I want to show you a new technique that allows you to launch volleys of arcane energy at your opponent, Arcane Missiles. You won\'t be able to cast this spell all the time, but each time you cast another spell, there\'s a chance you\'ll create an opening to use Arcane Missiles. I\'ll show you how it\'s done, and then I want you to go try it on one of the training dummies south of the entrance to the abbey.' WHERE `word_id` = 182758; -- locales_quest - details : entry=26916
UPDATE `trans_words` SET `content_loc7`='As a member of the Shattered Hand, you know that it is our job to watch the Horde\'s enemies. We have discovered that the Dark Iron dwarves and their new allies, Twilight\'s Hammer, are preparing to attack.$B$BI\'m sending you to help deal with this threat before the Dark Iron army marches. Take this poison and apply it to the soldiers\' rations of grain in Blackrock Depths.$B$BThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths.' WHERE `word_id` = 188252; -- locales_quest - details : entry=28463
UPDATE `trans_words` SET `content_loc7`='As a paladin, you\'re no stranger to the Light that touches all of us. But you also have the unique power to call upon the Light to help you in battle.$B$BWhile under the effects of the Seal of Righteousness, each melee attack will deal extra holy damage. From time to time, you can also use Judgement to unleash your seal\'s power for another attack.$B$BI want you to try out these techniques using the training dummies to the northwest of the Crash Site.' WHERE `word_id` = 182965; -- locales_quest - details : entry=26966
UPDATE `trans_words` SET `content_loc7`='As a priest, one of your most important duties is to use the Light\'s power to aid the wounded. There are no lack of people here who could use your skills, $N. Allow me to show you a quick, simple heal that you can use to treat any ally.$B$BUse your newfound knowledge to help me treat those wounded in the crash.' WHERE `word_id` = 182979; -- locales_quest - details : entry=26970
UPDATE `trans_words` SET `content_loc7`='As a priest, you will often be called upon to heal the wounds of injured comrades. I want to teach you a basic healing technique and with it, you will be able to ease the suffering of the wounded and hasten their recovery.$B$BUse your new knowledge to heal the injured sentinels recovering within Aldrassil.' WHERE `word_id` = 182891; -- locales_quest - details : entry=26949
UPDATE `trans_words` SET `content_loc7`='As a spirit, I am powerless, $N. Assist me. Allow me to regain my honor.' WHERE `word_id` = 137202; -- locales_quest - offerrewardtext : entry=2784
UPDATE `trans_words` SET `content_loc7`='As expected, my chosen knight has triumphed! You are ready, $N.' WHERE `word_id` = 161485; -- locales_quest - offerrewardtext : entry=12848
UPDATE `trans_words` SET `content_loc7`='As far as I\'m concerned, there\'s no problem that can\'t be solved with bombs. And if a bomb doesn\'t solve your problem on the first try... use a bigger bomb.$B$BSo there\'s this big worm that\'s been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks.$B$BHmm... there was one other thing I wanted to say... oh yeah! Don\'t get eaten.' WHERE `word_id` = 190548; -- locales_quest - details : entry=29263
UPDATE `trans_words` SET `content_loc7`='As far as you know, a worgen rogue roaming in Tirisfal is a new development. This is something that Executor Zygand would certainly be interested in.' WHERE `word_id` = 175926; -- locales_quest - details : entry=24992
UPDATE `trans_words` SET `content_loc7`='As fate would have it, there\'s a special deed that needs doing - one that will benefit the Cenarion Circle as well as myself.$B$BYou see, $C, I am under pressure to create a special... concoction, shall we say. I believe my work to be complete, but I need to have it tested to be certain.$B$BThe target of this test is to be the naga, who threaten this region from the west. Their demise would surely aid the Circle.$B$BFirst though, I need a delivery device. Hollow horns from the dying kodo should do nicely.' WHERE `word_id` = 174029; -- locales_quest - details : entry=14339
UPDATE `trans_words` SET `content_loc7`='As fun as it is to butt heads with these trolls, we\'ve got other things to do down here. It\'d be nice to get this battle over with, aye?$B$BTheir commander, Gan\'dranda, sits in the ruined walls to the southeast of the battlefield. Our boys have most of their forces locked up, so I want you to slip in there and take out Gan\'dranda. When they see a $R standin\' over the corpse of their biggest hero it should take some of the fight out of \'em!' WHERE `word_id` = 181208; -- locales_quest - details : entry=26483
UPDATE `trans_words` SET `content_loc7`='As I crossed the bridge into Dragonblight a small group of Anub\'ar ambushed me! I was surrounded! Those monsters knew I was coming. I barely made it out of there with my flesh intact. This list I hold must be taken to Wintergarde Keep, but I am too badly injured to make the journey.' WHERE `word_id` = 158776; -- locales_quest - offerrewardtext : entry=12157
UPDATE `trans_words` SET `content_loc7`='As I hinted earlier, I am no ordinary goblin. You may have already guessed my true identity.$B$BAllow me to show you my true form. As you have proven yourself trustworthy, I will also share with you the details of my plan.' WHERE `word_id` = 185694; -- locales_quest - details : entry=27769
UPDATE `trans_words` SET `content_loc7`='As I may have mentioned, I\'m trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.$B$BTo pull this off, we\'ve gotta pay lip service to the actual initiation process and all that, or I\'m going to catch flak later on. So I\'ve gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.$B$BI\'ve got a disguise for you here, so suit up and get all these signatures filled out.' WHERE `word_id` = 175780; -- locales_quest - details : entry=24955
UPDATE `trans_words` SET `content_loc7`='As I said, the rod giveth to our dark rangers and doth taketh away from our enemy!' WHERE `word_id` = 187839; -- locales_quest - offerrewardtext : entry=28331
UPDATE `trans_words` SET `content_loc7`='As I suspected, the water has turned red due to contamination from leaking core fluid.$B$BI hope you didn\'t swim in any of that contaminated water.' WHERE `word_id` = 272648; -- locales_quest - offerrewardtext : entry=9748
UPDATE `trans_words` SET `content_loc7`='As I understand it, you\'re to be looking to bring the Wildhammer clans together with the Alliance for war. Not sure you know what you\'re gettin\' into.$B$BAnyway, if it\'s battle you\'re preparin\' for, there\'s definitely one family you want by your side. Head southwest, to the opposite side of the Crucible of Carnage, and there you\'ll find Clan Dunwald\'s ruins. They\'re rightly ravaged, but that\'s not likely to be stoppin\' the Dunwalds. It\'s just a matter of findin\' them.' WHERE `word_id` = 185211; -- locales_quest - details : entry=27640
UPDATE `trans_words` SET `content_loc7`='As it happens there is something you can do to be of assistance, $C.' WHERE `word_id` = 161251; -- locales_quest - offerrewardtext : entry=12795
UPDATE `trans_words` SET `content_loc7`='As it turns out, the eggheads back at Honor Hold can\'t see much into this place. Bunch of lying lazy mages, is what they are.$B$BEither way, we don\'t really know exactly what\'s going on in here. So, you\'re going in to find out!' WHERE `word_id` = 191110; -- locales_quest - details : entry=29539
UPDATE `trans_words` SET `content_loc7`='As long as I am by your side the enemy will think of you as one of their own. Your newfound humanity, however, will not allow you to be reckless. If you draw attention to yourself the dwarves will grow suspicious and likely attack!$B$BWith that said, I have a plan. Take this barrel of poisoned water and use it to sate the thirst of the tired Stormpike trainees. Once they drink from it they will become deathly ill, eventually succumbing to the poison.' WHERE `word_id` = 188748; -- locales_quest - details : entry=28604
UPDATE `trans_words` SET `content_loc7`='As much as I dislike bringing such disease-ridden things into the village, they may give us an advantage over our foes.$B$B<The chieftain gestures to Sage Aeire and waves dismissively at the pelts.>$B$BWhile she is preparing the pelts, there is one other element we need to create the cloak.' WHERE `word_id` = 157110; -- locales_quest - offerrewardtext : entry=11628
UPDATE `trans_words` SET `content_loc7`='As much as I want to exact swift and brutal revenge... I must honor my son\'s memory first. He cared for his people first and foremost.$B$BThe Undertaker\'s Pass goes underground below Northgate River. You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic\'s Repose.$B$BWe captured one of the Forsaken\'s dreaded bombing bats. I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people. Hurry!' WHERE `word_id` = 175631; -- locales_quest - details : entry=24920
UPDATE `trans_words` SET `content_loc7`='As much as it irritates me that we may have assisted the Alliance, I declare the field test a success! Next stop: Agmar\'s Hammer!' WHERE `word_id` = 159042; -- locales_quest - offerrewardtext : entry=12218
UPDATE `trans_words` SET `content_loc7`='As my master told me... Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, $N, prevents the muisek from escaping. Now we may use it as we please!' WHERE `word_id` = 177153; -- locales_quest - offerrewardtext : entry=25336
UPDATE `trans_words` SET `content_loc7`='As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.$B$BThese deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns.$B$BIf you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.' WHERE `word_id` = 182625; -- locales_quest - details : entry=26872
UPDATE `trans_words` SET `content_loc7`='As part of a ritual to complete your training here in Shadowglen, you must learn about our recent history.$B$BThere is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.$B$BWhen you are done there, bring the water back to me, and I will direct you further.' WHERE `word_id` = 189114; -- locales_quest - details : entry=28729
UPDATE `trans_words` SET `content_loc7`='As pointless as I think that this is going to be, we need to investigate all of our leads.$B$BI need you to head out to the Longshore, west of here, on the coast, and shake up some murlocs. Try to find a clue or some info that can help shed some light on the murders.$B$BReturn to me if you get lucky, rookie.' WHERE `word_id` = 180280; -- locales_quest - details : entry=26214
UPDATE `trans_words` SET `content_loc7`='As promised, $N, here\'s your recipe! I\'m also going to throw in a little something extra for all of your hard work and dedication. What am I going to do with these anyway???' WHERE `word_id` = 139880; -- locales_quest - offerrewardtext : entry=5124
UPDATE `trans_words` SET `content_loc7`='As promised, $N. The entirety of the book\'s raw power, condensed into a single rune.' WHERE `word_id` = 150953; -- locales_quest - offerrewardtext : entry=10416
UPDATE `trans_words` SET `content_loc7`='As promised, Dreamwalker Legguards.$B$B<Rayne hands you the armor.>' WHERE `word_id` = 144973; -- locales_quest - offerrewardtext : entry=9087
UPDATE `trans_words` SET `content_loc7`='As promised, here is the key to Shaffar\'s personal stasis chamber.' WHERE `word_id` = 153173; -- locales_quest - offerrewardtext : entry=10981
UPDATE `trans_words` SET `content_loc7`='As promised, you have your choice, $N. The muisek of the creatures has been forever sealed into the power of these weapons.$B$BYou may now wield their energy as your own. Use it well.' WHERE `word_id` = 137922; -- locales_quest - offerrewardtext : entry=25391
UPDATE `trans_words` SET `content_loc7`='As promised, your reward. You do the troll nation proud.' WHERE `word_id` = 181014; -- locales_quest - offerrewardtext : entry=26405
UPDATE `trans_words` SET `content_loc7`='As quickly as it started, the Sparklematic 5200 comes to an abrupt halt. A simple "ding" is heard from the machine, and the mouth of the machine spirals upward. Inside the Sparklematic 5200 is a small box wrapped in a little bow. The machine would appear to wrap an object up after eliminating its grime-encrusted status. Even if the machine didn\'t work, at least the item is now wrapped in a pretty box.$B$BWell, there is one way to find out if it cleaned the item or not...' WHERE `word_id` = 137544; -- locales_quest - offerrewardtext : entry=2952
UPDATE `trans_words` SET `content_loc7`='As quickly as we\'re able to fill the trench, the iron dwarves keep clearing it. Our assault from above will not take the city alone. You must aid the earthen fighting in the plaza below.' WHERE `word_id` = 158038; -- locales_quest - offerrewardtext : entry=11982
UPDATE `trans_words` SET `content_loc7`='As reprehensible as your task was, it had to be done. Now you must look into the face of evil.' WHERE `word_id` = 147958; -- locales_quest - offerrewardtext : entry=9688
UPDATE `trans_words` SET `content_loc7`='As soon as all three of the fragments of the cipher are together, the ancient words will be known.$B$BRecovery of this fragment was no doubt challenging. You must be rewarded for such heroism.' WHERE `word_id` = 151568; -- locales_quest - offerrewardtext : entry=10579
UPDATE `trans_words` SET `content_loc7`='As soon as we arrived here at Light\'s Shield Tower, those two lunkhead paladins ran off to Light\'s Hope Chapel. It\'s still a ways away, but if we\'re going to follow Argus along his tour of the towers, this is about as close as we\'re going to get.$B$BCheck in on them and make sure they\'re alright?  I know they can handle themselves, but still, it\'d make me feel better to know that you were watching over them while I\'m stuck here with the caravan.' WHERE `word_id` = 184516; -- locales_quest - details : entry=27455
UPDATE `trans_words` SET `content_loc7`='As soon as we make our move west in order to attack Neferset City, the enemy will strike us from the east, where we\'ll be weak.$B$BNahom will be the first to fall, and if it does, Ramkahen will soon follow.$B$BA small detachment is there already.$B$BGet a briefing from them. I want you to make sure that they hold Nahom until I can send more troops there.' WHERE `word_id` = 188591; -- locales_quest - details : entry=28561
UPDATE `trans_words` SET `content_loc7`='As soon as we stopped, they made a bet about "who could kill the most undead in five minutes."$B$BIt\'s been an hour, and I\'m still waiting for them to come back.$B$BI saw Tarenar run off to the southeast. Unfortunately, I can\'t leave the caravan here by itself. If you end up traveling in that direction, could you find him and send him back to me?' WHERE `word_id` = 184258; -- locales_quest - details : entry=27370
UPDATE `trans_words` SET `content_loc7`='As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.$B$BHere mon, your reward as I promised. It\'s small in comparison to the gratification of knowing the naga fried for their hated act upon my crew.' WHERE `word_id` = 141080; -- locales_quest - offerrewardtext : entry=6143
UPDATE `trans_words` SET `content_loc7`='As Teldrassil purges itself of the corruption that has perverted it\'s growth for all of these years, a malevolent growth has formed near the tree\'s edge, south of here. We have an opportunity to strike out and purge the source of the fel moss that has tainted the gnarlpine, the timberlings, and everything else.$B$BWith the water that you\'ve collected from the moonwells and the renewed strength of Teldrassil herself, I can grant you great power for a short while. Put an end to this corruption, $N.' WHERE `word_id` = 173081; -- locales_quest - details : entry=14005
UPDATE `trans_words` SET `content_loc7`='As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below. The scream is followed by a roar.$B$BThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did. Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.' WHERE `word_id` = 132948; -- locales_quest - offerrewardtext : entry=26049
UPDATE `trans_words` SET `content_loc7`='As the Horde were marching upon Stonetalon, I noticed that some of the sentinels had fallen ill. Not long after, they started acting strangely. When the first tentacle burst from the ground the ill sentinels began attacking us. We lost the outpost shortly after...$B$BThe sentinels in the peak are now nothing more than shells - husks for something far more sinister. I want you to put the sentinels to rest and retrieve their glaives. Each glaive returned can identify a fallen sister.' WHERE `word_id` = 179235; -- locales_quest - details : entry=25913
UPDATE `trans_words` SET `content_loc7`='As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.$B$BMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.$B$BMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. I\'ll see to it that you\'re rewarded.' WHERE `word_id` = 190983; -- locales_quest - details : entry=29471
UPDATE `trans_words` SET `content_loc7`='As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.$B$BMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.$B$BMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you\'ll need from any trade goods vendor in Elwynn Forest or Mulgore.' WHERE `word_id` = 191058; -- locales_quest - details : entry=29515
UPDATE `trans_words` SET `content_loc7`='As the region becomes more lush, the creatures of the desert are being forced into increasingly confined spaces.$B$BA particularly distressing result is the impending extinction of the local swoops. Predators feast on the birds and their eggs when they take nest.$B$BI have acquired some swoop eggs from Tanaris and coated them with an irresistible pheromone. Place one in each nest you find, then protect it until a swoop comes to carry it off.$B$BYou will be doing a service to the balance of this land.' WHERE `word_id` = 173654; -- locales_quest - details : entry=14246
UPDATE `trans_words` SET `content_loc7`='As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used!$B$BThese supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water, we need to have it replicated in mass quantities.' WHERE `word_id` = 184192; -- locales_quest - details : entry=27352
UPDATE `trans_words` SET `content_loc7`='As the second defender falls to the ground, a chest appears in the back of the chamber. Could this be what they were protecting?' WHERE `word_id` = 186201; -- locales_quest - details : entry=27912
UPDATE `trans_words` SET `content_loc7`='As the soul clung to the keepsake, so shall it cling to the physical form of Ras Frostwhisper.' WHERE `word_id` = 140355; -- locales_quest - offerrewardtext : entry=5464
UPDATE `trans_words` SET `content_loc7`='As the stone goes quiet, you\'re left with a vague sense of unease. Something isn\'t right.$B$BPerhaps you should tell Skuerto of what you\'ve done so far.' WHERE `word_id` = 180786; -- locales_quest - details : entry=26346
UPDATE `trans_words` SET `content_loc7`='As the stone goes quiet, you\'re left with a vague sense of unease. Something isn\'t right.$B$BPerhaps you should tell Zaruk of what you\'ve done so far.' WHERE `word_id` = 182742; -- locales_quest - details : entry=26911
UPDATE `trans_words` SET `content_loc7`='As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear.' WHERE `word_id` = 134703; -- locales_quest - offerrewardtext : entry=1089
UPDATE `trans_words` SET `content_loc7`='As Tor\'gan taught me, I transfer the power and the spirit of the raptors into this orb. It will imbue our warriors with the fiery strength and intelligence of the raptor. The guile of the raptor is yours now as well, $C. Take it with pride, for the Horde!' WHERE `word_id` = 179934; -- locales_quest - offerrewardtext : entry=26108
UPDATE `trans_words` SET `content_loc7`='As Troteman cuts out, the world around you grows eerily silent. In the distance you see a full grown black dragon!' WHERE `word_id` = 182078; -- locales_quest - details : entry=26714
UPDATE `trans_words` SET `content_loc7`='As we chew up the resources of this land for our war machines, we deprive the local animals of their homes. If they are to die anyway, we should not allow that meat to go to waste. Not when the maw of Orgrimmar gapes open, hungry.$B$BKill the weakened mosshoof stags that remain in this area and collect their meat for our peons and grunts.' WHERE `word_id` = 173315; -- locales_quest - details : entry=14118
UPDATE `trans_words` SET `content_loc7`='As we struggled not to drown, my men and I were forced to abandon our weapons and much of our armor.$B$BErunak says to expect a major attack from the naga soon and I\'m inclined to believe him.$B$BIf we\'re going to stand a chance, we\'ll need your help to recover our lost armaments. They should be lying on the sea floor near our shipwrecks.$B$BHurry, $R, we\'re defenseless here.' WHERE `word_id` = 177806; -- locales_quest - details : entry=25545
UPDATE `trans_words` SET `content_loc7`='As we struggled not to drown, my orcs and I were forced to abandon our weapons and much of our armor.$B$BErunak says to expect a major attack from the naga soon and I believe him.$B$BIf we\'re going to be victorious, we\'ll need your help to recover our lost equipment.$B$BYou should find it scattered around the sea floor near our shipwrecks here and to the north.$B$BMake haste, $R. The enemy could arrive at any moment.' WHERE `word_id` = 179366; -- locales_quest - details : entry=25944
UPDATE `trans_words` SET `content_loc7`='As we suspected, the Magram have been stealing our supplies. We shall guard them more closely.' WHERE `word_id` = 173939; -- locales_quest - offerrewardtext : entry=14316
UPDATE `trans_words` SET `content_loc7`='As we would say in the Tinker\'s Union, out of the heat-applied metallic cooking container and into the oxydizing, energetic mixture of reacting gases and solids!' WHERE `word_id` = 176637; -- locales_quest - offerrewardtext : entry=25184
UPDATE `trans_words` SET `content_loc7`='As with any offensive, you first need to soften them up. We\'ve been having a heck of a time getting in there. But someone like you... well, let\'s just say I have no doubt in my mind that you can get into the Twilight Gate to the southwest and teach the Bloodeye Clan ogres and ettins a thing or two!' WHERE `word_id` = 184680; -- locales_quest - details : entry=27492
UPDATE `trans_words` SET `content_loc7`='As ya test yeself, ya\'ll find ya have better an\' better control o\'er da spirits--ya\'ll be callin\' on dem fer greata an\' greata tings... dat\'s where ol\' Ken\'jai come in. You come talk to ole Ken\'jai when ya feel yer ready. If da spirits agree, den we see \'bout teachin\' ya more powerful abilities... but only if da spirits agree.$B$BGo now, talk to da rest of da Valley\'s people. Speak to me again later.' WHERE `word_id` = 137746; -- locales_quest - offerrewardtext : entry=3085
UPDATE `trans_words` SET `content_loc7`='As yes, a voucher from the Explorers\' League... and quite the valuable one, might I add.$B$BThe Explorers\' League lends me the authority to offer you a choice in your compensation directly from their vault. You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward.' WHERE `word_id` = 136849; -- locales_quest - offerrewardtext : entry=2439
UPDATE `trans_words` SET `content_loc7`='As you anchor the tooth in Arngrim\'s jaw, you get the impression that your efforts may have taken the edge off of the old king\'s hunger pangs... for now.' WHERE `word_id` = 162324; -- locales_quest - offerrewardtext : entry=13046
UPDATE `trans_words` SET `content_loc7`='As you can see, $C, we still need to pack away more food for the soldiers. I don\'t know if you\'ve ever been in a war before, but once you get past the initial shock of the battlefield, you can get pretty hungry. You did a good job last time, so I expect that you\'ll do as well, if not a little quicker, in getting me another stack of those lean wolf steaks.' WHERE `word_id` = 144031; -- locales_quest - details : entry=8612
UPDATE `trans_words` SET `content_loc7`='As you can see, $N, our first assault on the Armory did not go as planned. We had taken the nearby courtyard until the Scarlet Champion, Herod, showed up.$B$BWe must continue our assault. The Scarlet Crusade will never be allowed to train another warrior here, let alone launch an attack on the Undercity.$B$BYour task should be obvious. Down the Scarlet Champion.' WHERE `word_id` = 182949; -- locales_quest - details : entry=26962
UPDATE `trans_words` SET `content_loc7`='As you can see, the Scourge war machine presses onward, yet the armies of the Horde and the Alliance remain divided, making for easy prey. It is for this reason that we must remain united.$B$B<Valus is lost in contemplation for a moment.>$B$BThe Argent Crusade has use for a $G man:woman; like you. Perhaps you would be interested in joining our cause? To battle and die at the side of the Ashbringer?' WHERE `word_id` = 160150; -- locales_quest - offerrewardtext : entry=12545
UPDATE `trans_words` SET `content_loc7`='As you can see, there was nothing I could have done.' WHERE `word_id` = 139074; -- locales_quest - offerrewardtext : entry=4342
UPDATE `trans_words` SET `content_loc7`='As you can see, they\'re all monsters! Most of my guards died and the ones that managed to escape are now holding down the barricades, preventing any of these potentially dangerous creatures from getting out.$B$BWe need your help!' WHERE `word_id` = 187277; -- locales_quest - offerrewardtext : entry=28192
UPDATE `trans_words` SET `content_loc7`='As you coat the helm with a thin layer of oil, the frost falls away and the surface gleams.' WHERE `word_id` = 162205; -- locales_quest - offerrewardtext : entry=13006
UPDATE `trans_words` SET `content_loc7`='As you continue to gain power, return to me and I will teach you new spells and techniques.' WHERE `word_id` = 180237; -- locales_quest - offerrewardtext : entry=26201
UPDATE `trans_words` SET `content_loc7`='As you continue your career as a warlock, you\'ll find it helpful to keep your spellbook filled with the latest incantations. Lucky for you, I know these spells, and I\'m willing to train you... for a price.' WHERE `word_id` = 175841; -- locales_quest - details : entry=24968
UPDATE `trans_words` SET `content_loc7`='As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a $C and what you are capable of.$B$BThese are dangerous times, $N, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again.' WHERE `word_id` = 137870; -- locales_quest - offerrewardtext : entry=3117
UPDATE `trans_words` SET `content_loc7`='As you gaze into the stone, your vision begins to swirl...' WHERE `word_id` = 147361; -- locales_quest - offerrewardtext : entry=9529
UPDATE `trans_words` SET `content_loc7`='As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.' WHERE `word_id` = 137818; -- locales_quest - offerrewardtext : entry=3103
UPDATE `trans_words` SET `content_loc7`='As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.$B$BAs you grow more powerful, return to me and I will teach you more about our ways.' WHERE `word_id` = 334411; -- locales_quest - offerrewardtext : entry=3105
UPDATE `trans_words` SET `content_loc7`='As you have by now witnessed, the rapid changes to this region can have both positive and negative effects on the native creatures.$B$BTo the south and east of here, enraged kodo are a constant threat to anyone nearby.$B$BIt\'s time to put my theory to the test. I\'ve used the rejuvenated thunder lizard\'s blood in the making of this concoction. I\'m hoping it will soothe the kodo when they eat it.$B$BPlace it near an enraged kodo and make sure you do it from a safe distance!' WHERE `word_id` = 173906; -- locales_quest - details : entry=14309
UPDATE `trans_words` SET `content_loc7`='As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade.$B$BYou will find him in the village of Nighthaven.' WHERE `word_id` = 183995; -- locales_quest - details : entry=27283
UPDATE `trans_words` SET `content_loc7`='As you have no doubt noticed by now, the recent changes to the land have had many side-effects. Some of these are beneficial, while others pose serious problems.$B$BJust south of the village the local lobstrok are emerging from the sea and choking off the road to the village.$B$BPlease, $C, go and thin the numbers of this pest.' WHERE `word_id` = 174013; -- locales_quest - details : entry=14335
UPDATE `trans_words` SET `content_loc7`='As you know, $N, Garrosh has relegated the Goblins of Orgrimmar to the western outskirts of the city. Fortunately, that means that we have easy access to their supplies. I am working on a large batch of jambalaya for the infantry and I need as much rice as possible. Lucky for us, the Goblins keep it stored in barrels near their structures. Retrieve these barrels of Kezan rice for me and I should be able to finish up.' WHERE `word_id` = 180352; -- locales_quest - details : entry=26234
UPDATE `trans_words` SET `content_loc7`='As you know, $N, Garrosh has relegated the Trolls of Orgrimmar to the western outskirts of the city. Fortunately, that means that we have easy access to their supplies. I am working on a large batch of jambalaya for the infantry and I need as much rice as possible. Lucky for us, the Trolls keep it stored in barrels near their structures. Retrieve these barrels of Darkspear rice for me and I should be able to finish up.' WHERE `word_id` = 180348; -- locales_quest - details : entry=26233
UPDATE `trans_words` SET `content_loc7`='As you lay your hand upon the chest, a faint rumbling can be heard. The sound of grinding movement echoes behind you as the chest begins to shut itself.$B$BSomething is approaching!' WHERE `word_id` = 176233; -- locales_quest - details : entry=25070
UPDATE `trans_words` SET `content_loc7`='As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01\'s shoulder, the other is on her head.$B$BNo power seems to be running through her components as you investigate further.' WHERE `word_id` = 138918; -- locales_quest - offerrewardtext : entry=4243
UPDATE `trans_words` SET `content_loc7`='As you look over the ruins of the camp, you hear a whisper behind you. <"I could kill you right now if I wanted to. You\'d better watch your step, $R.">' WHERE `word_id` = 175997; -- locales_quest - offerrewardtext : entry=25010
UPDATE `trans_words` SET `content_loc7`='As you may have seen, the ship docked to the north has its cannons blazing. While it\'s pretty fun watching the gnomes run face-first into a hail of iron, my bruisers keep doing it too, and it\'s absolutely killing my overhead expenses.$B$BI\'d like you to try and dance through the cannonfire, get on that ship, and kill the taskmaster leading the cannoneers. The rest of the crew is probably a bunch of spineless prats; once he\'s down, we should be good.' WHERE `word_id` = 177759; -- locales_quest - details : entry=25534
UPDATE `trans_words` SET `content_loc7`='As you of course know, $N, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!$B$BWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault. Once there, use Maurin\'s Concoction to teach them a lesson they shall not soon forget.' WHERE `word_id` = 174059; -- locales_quest - details : entry=14346
UPDATE `trans_words` SET `content_loc7`='As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.$B$B"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn\'t want to fix another one, would ya?"' WHERE `word_id` = 334060; -- locales_quest - offerrewardtext : entry=983
UPDATE `trans_words` SET `content_loc7`='As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.' WHERE `word_id` = 133475; -- locales_quest - offerrewardtext : entry=779
UPDATE `trans_words` SET `content_loc7`='As you place the statue in its place, several other stone statues appear in the room. One more ruby-colored statue also appears, in a small enclosure on the far end of the room. You hear a voice:$B$B  "The Sentinel watches.$B  The Sentinel protects.$B   The Sentinel\'s vision never falters."$B$BThat red statue on the other side of the room looks important. Perhaps you should try to connect the two red statues?' WHERE `word_id` = 185480; -- locales_quest - details : entry=27709
UPDATE `trans_words` SET `content_loc7`='As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.$B$BOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you\'ve gained more power, come to me and I shall teach you what I can.' WHERE `word_id` = 137742; -- locales_quest - offerrewardtext : entry=3084
UPDATE `trans_words` SET `content_loc7`='As you read the totem, your mouth forms the word V-A-R-K. You understand this to mean justice.' WHERE `word_id` = 147413; -- locales_quest - offerrewardtext : entry=9542
UPDATE `trans_words` SET `content_loc7`='As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there\'s no blood to be found, and no remains of any bodies.$B$BWhoever attacked the wagon was efficient and swift.' WHERE `word_id` = 135607; -- locales_quest - offerrewardtext : entry=1437
UPDATE `trans_words` SET `content_loc7`='As you rummage through Teronis\' belongings, you find a journal that is still in good condition.$B$BYou take the journal and leave Teronis\' corpse as is.$B$BThe only thing left to do is find the gem Teronis was seeking. Orendil mentioned it being in the area. Perhaps the tendrils have it...?' WHERE `word_id` = 166796; -- locales_quest - details : entry=1023
UPDATE `trans_words` SET `content_loc7`='As you rummage through Teronis\' belongings, you find a water-damaged journal.$B$BQuickly flipping through the last legible pages, you read that Teronis makes mention of finding the gem, but then of having lost it in the Falathim area.$B$BThe only thing left to do is find it. Perhaps the tendrils have it...?' WHERE `word_id` = 181181; -- locales_quest - details : entry=26464
UPDATE `trans_words` SET `content_loc7`='As you search through the belongings of the dead furbolg lying before you, a small charm, very obviously created by trolls, spills out onto the ground.$B$BTouching the charm, you immediately get a sense that something is not right about the wood. A feeling of unease, of corruption, permeates the object.$B$BWrapping it in some spare cloth, you put it in your pack and resolve to show it to Raene Wolfrunner when next you find yourself in Astranaar.' WHERE `word_id` = 172621; -- locales_quest - details : entry=13868
UPDATE `trans_words` SET `content_loc7`='As you slaughter their enemy, the Gelkis clan cannot help but to acknowledge your prowess.' WHERE `word_id` = 173993; -- locales_quest - offerrewardtext : entry=14329
UPDATE `trans_words` SET `content_loc7`='As you slide the chain back around the denmother\'s neck she licks your face approvingly.' WHERE `word_id` = 162144; -- locales_quest - offerrewardtext : entry=12994
UPDATE `trans_words` SET `content_loc7`='As you slip the tablet into the voodoo pile, a primal screech shatters the silence.' WHERE `word_id` = 190176; -- locales_quest - offerrewardtext : entry=29262
UPDATE `trans_words` SET `content_loc7`='As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack. A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.$B$B"Salutations. I am a guardian of entry. The discs that have been used for access are missing the correct entry discs, the Plates of Uldum. Please incorporate these plates with the disc structure and repeat your access sequencing. Thank you."' WHERE `word_id` = 137571; -- locales_quest - offerrewardtext : entry=2946
UPDATE `trans_words` SET `content_loc7`='As you turn around, you see the silhouettes of shambling skeletons on the stairs.$B$BThe undead aren\'t gone from this crypt. They were lying in wait!  Furthermore, they appear to be armed with the weapons that you came looking for.$B$BYou\'ll have to escape from the crypt. On your way out, you should gather as many pieces of equipment as you can.' WHERE `word_id` = 183714; -- locales_quest - details : entry=27171
UPDATE `trans_words` SET `content_loc7`='As you well know, the amount of energy stored in a conventional spring is equal to one half the spring\'s elasticity times the displacement squared. Unless you\'re using an elementium spring. Then the numbers get obscene! Mathematically grotesque!$B$BI need some elementium loops for my secret weapon, and it just so happens that Twilight\'s Hammer cultists use coils like that to bind earth elementals.$B$BFind them on the Obsidian Stoneslaves east of here, in the terrible region known as the Black Breach.' WHERE `word_id` = 187368; -- locales_quest - details : entry=28215
UPDATE `trans_words` SET `content_loc7`='As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.$B$BHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.$B$BThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.' WHERE `word_id` = 177330; -- locales_quest - details : entry=25396
UPDATE `trans_words` SET `content_loc7`='As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.$B$BWeeks ago, in the glade to the west, I saw the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.$B$BThough the giants weep no more, these stonetears must be what Ysondre referred to; a source of nature\'s purity. We must gather them.' WHERE `word_id` = 176855; -- locales_quest - details : entry=25237
UPDATE `trans_words` SET `content_loc7`='As you\'re probably already realizing, the Royal Apothecary Society is a widespread organization. We take our plague-alchemy seriously. It is our belief that the more agents we have performing experiments, the sooner we will realize our objective.$B$BOne of our agents performs his work at a small encampment to the north of here. His name is Jerrod, and he could use an apprentice of your... stature.' WHERE `word_id` = 175922; -- locales_quest - details : entry=24991
UPDATE `trans_words` SET `content_loc7`='As you\'ve been told by now, we are to escort a diplomat from within the besieged lumber camp to safety.$B$BAs it stands, that\'s simply impossible. The elves have a thousand arrows trained on the camp\'s exits.$B$BFirst we must create a diversion - something that will take their eyes off of the camp for a time.$B$BMy idea is simple. Take this axe and cut down the trees they\'ve been nurturing in the region.$B$BWhen you\'re through, use the signal powder here to speak with me again.' WHERE `word_id` = 172567; -- locales_quest - details : entry=13815
UPDATE `trans_words` SET `content_loc7`='As you\'ve now witnessed, the Legion forces work tirelessly, manipulating the Sunwell\'s power to achieve their malevolent ends.$B$BKael\'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.' WHERE `word_id` = 191330; -- locales_quest - details : entry=29685
UPDATE `trans_words` SET `content_loc7`='Ascend the Charred Vale' WHERE `word_id` = 179310; -- locales_quest - EndText : entry=25930
UPDATE `trans_words` SET `content_loc7`='Ashelan was good to send you. There is indeed a wicked plot underway in this corrupted place.' WHERE `word_id` = 182657; -- locales_quest - offerrewardtext : entry=26881
UPDATE `trans_words` SET `content_loc7`='Ashenvale Bowmen Slain' WHERE `word_id` = 172329; -- locales_quest - ObjectiveText2 : entry=13612
UPDATE `trans_words` SET `content_loc7`='Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.' WHERE `word_id` = 141398; -- locales_quest - offerrewardtext : entry=6541
UPDATE `trans_words` SET `content_loc7`='Ashenvale Oaks Chopped Down' WHERE `word_id` = 172570; -- locales_quest - ObjectiveText1 : entry=13815
UPDATE `trans_words` SET `content_loc7`='Ashenvale Scouts defeated' WHERE `word_id` = 172611; -- locales_quest - ObjectiveText4 : entry=13865
UPDATE `trans_words` SET `content_loc7`='Ashenvale Skirmishers Slain' WHERE `word_id` = 172328; -- locales_quest - ObjectiveText1 : entry=13612
UPDATE `trans_words` SET `content_loc7`='Ashenvale Wreckers destroyed' WHERE `word_id` = 172372; -- locales_quest - ObjectiveText1 : entry=13624
UPDATE `trans_words` SET `content_loc7`='Ashenvale? Hmm, I had not heard of any presence of the Council or the Burning Blade in Ashenvale. My spies will investigate, $N. You have done well.$B$BFor now, rest, and keep yourself occupied with other tasks. I will call upon you again soon.$B$BLok-Tar Ogar!' WHERE `word_id` = 140672; -- locales_quest - offerrewardtext : entry=5730
UPDATE `trans_words` SET `content_loc7`='Ashlan\'s no doubt going to send you off to the Loch to investigate the Dark Iron hooligans he keeps muttering about. If you\'re headed down there, might as well make some coin while you\'re at it, right?$B$BThe loch\'s draining wiped out most of the wildlife in it. Not many places to swim anymore. But there\'s still crocolisks padding around on the now-dry ground.$B$BThey\'ll starve in time, so we may as well get \'em while they\'re fresh. Bring me back some full sides of croc and we\'ll talk rewards.' WHERE `word_id` = 176412; -- locales_quest - details : entry=25119
UPDATE `trans_words` SET `content_loc7`='Ashley rescued' WHERE `word_id` = 174116; -- locales_quest - ObjectiveText2 : entry=14368
UPDATE `trans_words` SET `content_loc7`='Ask Chieftain Swiftspear about his memories' WHERE `word_id` = 162277; -- locales_quest - ObjectiveText1 : entry=13037
UPDATE `trans_words` SET `content_loc7`='Ask Ergll about Azuregos' WHERE `word_id` = 173387; -- locales_quest - EndText : entry=14133
UPDATE `trans_words` SET `content_loc7`='Ask Ergll about Azuregos.' WHERE `word_id` = 173386; -- locales_quest - objectives : entry=14133
UPDATE `trans_words` SET `content_loc7`='Ask Krasus about the hilt\'s origins' WHERE `word_id` = 164936; -- locales_quest - ObjectiveText1 : entry=14444
UPDATE `trans_words` SET `content_loc7`='Ask Maruut Stonebinder about the World Pillar.' WHERE `word_id` = 180385; -- locales_quest - objectives : entry=26243
UPDATE `trans_words` SET `content_loc7`='Assassinate Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion.' WHERE `word_id` = 187025; -- locales_quest - objectives : entry=28136
UPDATE `trans_words` SET `content_loc7`='Assassinate General Marstone.' WHERE `word_id` = 184993; -- locales_quest - objectives : entry=27580
UPDATE `trans_words` SET `content_loc7`='Assemble the Samophlange Manual.' WHERE `word_id` = 173086; -- locales_quest - objectives : entry=14006
UPDATE `trans_words` SET `content_loc7`='Assemble the true name by examining the three Firestones in the Inferno.' WHERE `word_id` = 177480; -- locales_quest - objectives : entry=25443
UPDATE `trans_words` SET `content_loc7`='Assemble the true name by examining the three Firestones.' WHERE `word_id` = 177394; -- locales_quest - objectives : entry=25412
UPDATE `trans_words` SET `content_loc7`='Assess the situation at the Sludge Fields.' WHERE `word_id` = 187276; -- locales_quest - EndText : entry=28192
