UPDATE `trans_words` SET `content_loc7`='Bites of Murkgill meat' WHERE `word_id` = 180690; -- locales_quest - ObjectiveText1 : entry=26321
UPDATE `trans_words` SET `content_loc7`='Bjorn Halgurdsson defeated' WHERE `word_id` = 159869; -- locales_quest - ObjectiveText2 : entry=12481
UPDATE `trans_words` SET `content_loc7`='Bjorn Halgurdsson insulted' WHERE `word_id` = 159868; -- locales_quest - ObjectiveText1 : entry=12481
UPDATE `trans_words` SET `content_loc7`='Black Knight\'s Gryphon taken' WHERE `word_id` = 164024; -- locales_quest - ObjectiveText1 : entry=13663
UPDATE `trans_words` SET `content_loc7`='Blackfathom Tide Priestesses slain' WHERE `word_id` = 172762; -- locales_quest - ObjectiveText1 : entry=13901
UPDATE `trans_words` SET `content_loc7`='Blackhorn Persuaded' WHERE `word_id` = 177359; -- locales_quest - ObjectiveText1 : entry=25404
UPDATE `trans_words` SET `content_loc7`='Blackrock Depths has long been home to our enemies, but now SI:7 sends word that the Dark Irons and Twilight\'s Hammer are increasing their collaboration. Using the knowledge of the cult, the Dark Iron dwarves are imbuing their weapons with elemental powers. They\'ve outfitted the Anvilrage legion with these fearsome new weapons.$B$BI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.' WHERE `word_id` = 188144; -- locales_quest - details : entry=28405
UPDATE `trans_words` SET `content_loc7`='Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight\'s Hammer are increasing their collaboration. Using the cult\'s knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They\'ve outfitted the Anvilrage legion with these fearsome new weapons.$B$BI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.' WHERE `word_id` = 188257; -- locales_quest - details : entry=28466
UPDATE `trans_words` SET `content_loc7`='Blackrock minions cudgeled' WHERE `word_id` = 187633; -- locales_quest - ObjectiveText1 : entry=28278
UPDATE `trans_words` SET `content_loc7`='Blackrock Orcs of Alther\'s Mill or Render\'s Camp slain' WHERE `word_id` = 181541; -- locales_quest - ObjectiveText1 : entry=26570
UPDATE `trans_words` SET `content_loc7`='Blackrock Sergeant slain' WHERE `word_id` = 187638; -- locales_quest - ObjectiveText1 : entry=28279
UPDATE `trans_words` SET `content_loc7`='Blackrock troop slain' WHERE `word_id` = 187241; -- locales_quest - ObjectiveText1 : entry=28184
UPDATE `trans_words` SET `content_loc7`='Blackrock War Kodos summoned back to camp' WHERE `word_id` = 187522; -- locales_quest - ObjectiveText1 : entry=28252
UPDATE `trans_words` SET `content_loc7`='Blackscale Naga Slain' WHERE `word_id` = 183745; -- locales_quest - ObjectiveText1 : entry=27178
UPDATE `trans_words` SET `content_loc7`='Blacksilt Scouts Tagged' WHERE `word_id` = 147760; -- locales_quest - ObjectiveText1 : entry=9629
