UPDATE `trans_words` SET `content_loc7`='Blade blooded on Sapphire Hive Wasp' WHERE `word_id` = 161032; -- locales_quest - ObjectiveText1 : entry=12734
UPDATE `trans_words` SET `content_loc7`='Blades buried' WHERE `word_id` = 184573; -- locales_quest - ObjectiveText1 : entry=27467
UPDATE `trans_words` SET `content_loc7`='Bladespire Hold building cursed' WHERE `word_id` = 151412; -- locales_quest - ObjectiveText1 : entry=10544
UPDATE `trans_words` SET `content_loc7`='Bladespire Ogres drunk' WHERE `word_id` = 151306; -- locales_quest - ObjectiveText1 : entry=10512
UPDATE `trans_words` SET `content_loc7`='Bladespire Ogres killed' WHERE `word_id` = 151262; -- locales_quest - ObjectiveText1 : entry=10503
UPDATE `trans_words` SET `content_loc7`='Blast it all!$B$BSomeone\'s gone and corrupted the entire system! There be no way fer me ta access the main repository from this console.$B$BWe\'re gunna hafta do this the hard way, $Glad:lass;. I hope you an\' yer friends here are up to a fight.$B$BThere be four guardians on the upper level of this place. I won\'t be able ta utilize these discs \'til they be... uhh, offline, shall we say.' WHERE `word_id` = 189197; -- locales_quest - details : entry=28753
UPDATE `trans_words` SET `content_loc7`='Blasted Horde! I\'ve got friends at that grove. Hopefully you know how to ride a hippogryph. We\'ve got to get you to Master Thal\'darah at the overlook immediately!' WHERE `word_id` = 179077; -- locales_quest - offerrewardtext : entry=25877
UPDATE `trans_words` SET `content_loc7`='Blastgineer Fuzzwhistle is definitely dead. It\'s probably for the best. It looks like he\'s holding a note in his hand.' WHERE `word_id` = 179548; -- locales_quest - offerrewardtext : entry=26001
UPDATE `trans_words` SET `content_loc7`='Blastshadow\'s Soulstone destroyed' WHERE `word_id` = 176433; -- locales_quest - ObjectiveText1 : entry=25123
UPDATE `trans_words` SET `content_loc7`='Blazerunner, you say...$B$BYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him.' WHERE `word_id` = 138684; -- locales_quest - offerrewardtext : entry=4005
UPDATE `trans_words` SET `content_loc7`='Bless yer heart. stranger. This\'ll go a long ways in liftin\' the morale o\' the crew.' WHERE `word_id` = 147278; -- locales_quest - offerrewardtext : entry=9512
UPDATE `trans_words` SET `content_loc7`='Bless you child! With your help, the Light shines even in the darkest of places.$B$BPlease, take this as just compensation for your good deeds. I shall see to the salvation of those you freed; at least, those truly within the Light, and the Alliance, who returned here to the keep.' WHERE `word_id` = 155342; -- locales_quest - offerrewardtext : entry=11231
UPDATE `trans_words` SET `content_loc7`='Bless your heart, $N. You truly are a hero of the Alliance! Though the land is completely incinerated and there is nothing left of the vineyard but ash and debris, I still might be able to recover. Right? How bad can it be?' WHERE `word_id` = 180961; -- locales_quest - offerrewardtext : entry=26391
UPDATE `trans_words` SET `content_loc7`='Bless your heart, dear. These poor orphans haven\'t had a hot meal in days. It looks like we will have enough left over to help feed many more of the homeless of Westfall.' WHERE `word_id` = 180380; -- locales_quest - offerrewardtext : entry=26241
UPDATE `trans_words` SET `content_loc7`='Blessed be the Light! I need your help!$B$BOn my way into Hillsbrad I noticed several families of adorable little deer. As I went out to pet one of the little fawns a ravenous mountain cat leapt out and killed it. I fled to Tarren Mill and swore to solve the plight of the hill fawn. Now, after many days of tinkering, I have created the hill fawn\'s salvation!$B$BTake my wand into the fields to the west and use it to empower the wee hill fawns. Once empowered they will be able to fend for themselves!' WHERE `word_id` = 188345; -- locales_quest - details : entry=28495
UPDATE `trans_words` SET `content_loc7`='Blessed bootstraps! Are those what I think they are? The troops have been complaining non-stop about the lack of storage space for all that is required while in the field. One of them even drew me a diagram - such a pansy...$B$BThese will definitely help alleviate some of the whining.' WHERE `word_id` = 145141; -- locales_quest - offerrewardtext : entry=9191
UPDATE `trans_words` SET `content_loc7`='Blessed Light! We have taken the pinnacle! Finally, construction of Justice Keep can begin. Highlord Fordring and the knights are already en route to our new base. You must meet them there, $N!' WHERE `word_id` = 162755; -- locales_quest - offerrewardtext : entry=13141
UPDATE `trans_words` SET `content_loc7`='Blessings onto you, friend $C! Your donation goes far beyond what was needed. Your sacrifice will not only help us recover what we have lost, but also help us to help those most in need here in Ironforge.$B$BNow, let me make sure I\'ve suitably prepared this censer for your future needs...' WHERE `word_id` = 142266; -- locales_quest - offerrewardtext : entry=7637
UPDATE `trans_words` SET `content_loc7`='Blessings upon you. Please accept this as a token of my gratitude.' WHERE `word_id` = 189232; -- locales_quest - offerrewardtext : entry=28760
