UPDATE `trans_words` SET `content_loc7`='Boss! Er, well, I guess you\'re not the boss anymore, but still, good to see you! Can you believe it? We\'ve got a cave full of intelligent killer monkeys mining Kaja\'mite!' WHERE `word_id` = 173665; -- locales_quest - offerrewardtext : entry=14248
