UPDATE `trans_words` SET `content_loc7`='Braug sent you? Impossible.$B$B<Parqual looks you up and down.>$B$BBraved Dor\'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You\'re probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... $C.' WHERE `word_id` = 134989; -- locales_quest - offerrewardtext : entry=1159
UPDATE `trans_words` SET `content_loc7`='Brave $C, you have proven yourself to be a great champion of the Horde.$B$BNow this collection of fetishes of Hakkar must be dealt with at once!' WHERE `word_id` = 135633; -- locales_quest - offerrewardtext : entry=1445
UPDATE `trans_words` SET `content_loc7`='Bravely done, $N.$B$BWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...$B$BRidding the Venture Company of its personnel is a good first move against them.' WHERE `word_id` = 134579; -- locales_quest - offerrewardtext : entry=1062
UPDATE `trans_words` SET `content_loc7`='Bravely done, $N.$B$BYou have given the Shade of Elura much deserved peace, and we will use the gathered elunite to make a fine weapon for you.' WHERE `word_id` = 136111; -- locales_quest - offerrewardtext : entry=1686
UPDATE `trans_words` SET `content_loc7`='Braves Freed' WHERE `word_id` = 175511; -- locales_quest - ObjectiveText1 : entry=24852
UPDATE `trans_words` SET `content_loc7`='Bravo, $N! Bravo! The bond of kinship between you and your falcon is strong! Perhaps you can run some reconnaissance missions against the vrykul in the not-too-distant future?' WHERE `word_id` = 156686; -- locales_quest - offerrewardtext : entry=11470
UPDATE `trans_words` SET `content_loc7`='Bravo, $N! Now let\'s take a look-see at our new situation. What? MORE murlocs? I swear on my stones, the more murlocs you kill, the more murlocs appear. Is it just me? We\'re going to need a new approach.' WHERE `word_id` = 172770; -- locales_quest - offerrewardtext : entry=13907
UPDATE `trans_words` SET `content_loc7`='Bravo, $N. I knew you would be victorious! The Legion\'s defeat draws ever nearer! ' WHERE `word_id` = 276284; -- locales_quest - offerrewardtext : entry=10389
UPDATE `trans_words` SET `content_loc7`='Braziers Hit' WHERE `word_id` = 154638; -- locales_quest - ObjectiveText1 : entry=11731
UPDATE `trans_words` SET `content_loc7`='Break 5 Darkwhisper Lodestones.' WHERE `word_id` = 177677; -- locales_quest - objectives : entry=25509
