UPDATE `trans_words` SET `content_loc7`='Commander Haephus Stonewall has asked you to kill Dorgok at Bloodmaul Camp. Return to him at Evergrove in the Blade\'s Edge Mountains after you have done the deed.' WHERE `word_id` = 152369; -- locales_quest - objectives : entry=10795
