UPDATE `trans_words` SET `content_loc7`='Corpsebeast destroyed' WHERE `word_id` = 184847; -- locales_quest - ObjectiveText1 : entry=27530
UPDATE `trans_words` SET `content_loc7`='Could it be that Kronus isn\'t really exaggerating? The titans\' stone and iron sons fighting against each other for control of the ancient city of Ulduar. This is madness, $N and it could destroy our only chance to learn the true history of dwarvenkind!' WHERE `word_id` = 158905; -- locales_quest - offerrewardtext : entry=12185
UPDATE `trans_words` SET `content_loc7`='Could it be? The man who wrote this journal feared for his daughters\' lives so he sent them away from Silverbrook.$B$BWe just captured an outcast in the outskirts of town about the same age as the eldest daughter.$B$BListen, $N. There\'s more happening here than meets the eye... we can\'t just burn this diary.' WHERE `word_id` = 159629; -- locales_quest - offerrewardtext : entry=12424
UPDATE `trans_words` SET `content_loc7`='Could this be?  Let me take a closer look at that mold.' WHERE `word_id` = 152202; -- locales_quest - offerrewardtext : entry=10754
UPDATE `trans_words` SET `content_loc7`='Could you be the first to earn favor among the Bronze Flight in a thousand years?' WHERE `word_id` = 143217; -- locales_quest - offerrewardtext : entry=8288
UPDATE `trans_words` SET `content_loc7`='Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.$B$BYou have served the Horde honorably, young $C.$B$BNow excuse me, I must counsel Thrall on these matters at once...' WHERE `word_id` = 133641; -- locales_quest - offerrewardtext : entry=831
UPDATE `trans_words` SET `content_loc7`='Coup de Grace delivered' WHERE `word_id` = 185455; -- locales_quest - ObjectiveText1 : entry=27702
UPDATE `trans_words` SET `content_loc7`='COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight! No matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!' WHERE `word_id` = 186009; -- locales_quest - offerrewardtext : entry=27850
