UPDATE `trans_words` SET `content_loc7`='Discuss marriage prospects with Keegan Firebeard at Kirthaven in Twilight Highlands.' WHERE `word_id` = 187906; -- locales_quest - objectives : entry=28346
UPDATE `trans_words` SET `content_loc7`='Diseased Vultures Slain' WHERE `word_id` = 186309; -- locales_quest - ObjectiveText1 : entry=27940
UPDATE `trans_words` SET `content_loc7`='Disgusting Eels Justifiably Slain' WHERE `word_id` = 177573; -- locales_quest - ObjectiveText1 : entry=25474
UPDATE `trans_words` SET `content_loc7`='Disgusting, but necessary I can assure you. You have done us good service by investigating this matter, Please, take this as a token of our generosity and appreciation.' WHERE `word_id` = 146461; -- locales_quest - offerrewardtext : entry=9193
UPDATE `trans_words` SET `content_loc7`='Disgusting, I know, but if we three are to be free of Kaliva\'s chains, it is not enough that she is dead. We must eat of her fel heart!' WHERE `word_id` = 172997; -- locales_quest - offerrewardtext : entry=13982
UPDATE `trans_words` SET `content_loc7`='Disgusting, isn\'t it? Look at them. Pathetic little things that can\'t even toil with their own bodies.$B$BThey stomp around in their massive metal shredders, carving the forest to splinters. I bet they think they\'re safe in there, all warm and cozy.$B$BProve them wrong. Blaze north through the camp and destroy as many shredders as you can. Once you\'ve spilled some blood, we\'re going to take this place apart for good.' WHERE `word_id` = 187864; -- locales_quest - details : entry=28337
UPDATE `trans_words` SET `content_loc7`='Dispatch of Queen Azshara.' WHERE `word_id` = 191516; -- locales_quest - objectives : entry=30100
