UPDATE `trans_words` SET `content_loc7`='Dreadlords!  They plan to attack us here at Splintertree Post?! Not while I still draw breath! No. We will not allow this to happen!  They are a blight upon our world!' WHERE `word_id` = 169238; -- locales_quest - offerrewardtext : entry=26447
UPDATE `trans_words` SET `content_loc7`='Dreadlords!  They plan to attack us here at Splintertree Post?!$B$BNot while I still draw breath!$B$B<Valusha crumples the demon-scrawled plans in her fist.>$B$BNo. We will not allow this to happen!  They are a blight upon our world!' WHERE `word_id` = 147386; -- locales_quest - offerrewardtext : entry=9535
UPDATE `trans_words` SET `content_loc7`='Drek\'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.$B$BYou have earned the Eye of Command.$B$BPresent your insignia, Commander $N.$B$B<Warmaster Laggrond salutes>' WHERE `word_id` = 141916; -- locales_quest - details : entry=7167
UPDATE `trans_words` SET `content_loc7`='Dried-up Scourge... weak. Abominations... strong.$B$BWe defeat strong abominations... we win war.' WHERE `word_id` = 183679; -- locales_quest - details : entry=27160
UPDATE `trans_words` SET `content_loc7`='Drill Sample Taken' WHERE `word_id` = 176783; -- locales_quest - ObjectiveText1 : entry=25217
