UPDATE `trans_words` SET `content_loc7`='Fill one of Sambino\'s Air Balloons and find his Lost Air Valve.' WHERE `word_id` = 176786; -- locales_quest - objectives : entry=25218
UPDATE `trans_words` SET `content_loc7`='Fill Sambino\'s Air Balloon' WHERE `word_id` = 176789; -- locales_quest - ObjectiveText1 : entry=25218
