UPDATE `trans_words` SET `content_loc7`='Fragile Twilight invaders litter the redoubt. They\'re pouring in from somewhere to the west.$B$BThere can be no mercy offered to them within this hallowed place. Whatever violence grips your moral heart, release it upon them.' WHERE `word_id` = 184738; -- locales_quest - details : entry=27507
