UPDATE `trans_words` SET `content_loc7`='Get to the bridge on the east, quickly. Lady Naz\'jar and the Fathom-Lord should be there with whatever forces remain.$B$BFollow our Lady\'s direction, as always. Hold the bridge until we can complete the ritual.$B$BOnce our allies arrive, the Kvaldir will be doomed.' WHERE `word_id` = 179398; -- locales_quest - details : entry=25951
UPDATE `trans_words` SET `content_loc7`='Get to the explosives in the catacombs beneath the Cathedral of Light!' WHERE `word_id` = 337665; -- locales_quest - completedText : entry=27092
UPDATE `trans_words` SET `content_loc7`='Get to the Hammer of Twilight.' WHERE `word_id` = 185761; -- locales_quest - objectives : entry=27784
