UPDATE `trans_words` SET `content_loc7`='Gilblingle Slain' WHERE `word_id` = 178561; -- locales_quest - ObjectiveText1 : entry=25738
UPDATE `trans_words` SET `content_loc7`='Gilblins!$B$B<Larry stares at you silently for a while.>$B$BYou never seen a gilblin before? They\'re crazy! Crazier than me! I just blow stuff up for a living, these guys are WHACKED!$B$BDunno where they came from, but they\'re like awful fish goblins! Gills and everything! They wiped out all my men down at the beach, and they took our shipping freighter!$B$BYou gotta help! They\'re just down to the east, go on and get rid of those gilblins!' WHERE `word_id` = 185049; -- locales_quest - details : entry=27598
UPDATE `trans_words` SET `content_loc7`='Ginormus Defeated' WHERE `word_id` = 176222; -- locales_quest - EndText : entry=25067
UPDATE `trans_words` SET `content_loc7`='Githyiss and her brood were being corrupted by this totem. This is a furbolg totem. This is very troubling indeed. This means the Gnarlpine are still a danger to these forests. We let our guard down too soon.' WHERE `word_id` = 189109; -- locales_quest - offerrewardtext : entry=28727
UPDATE `trans_words` SET `content_loc7`='Githyiss the Vile was known for possessing a poison more potent than any other webwood spider. Dirania Silvershrine at the base of Aldrassil would surely be interested in using Githyiss\' engorged venom sac to concoct an antidote equally as potent. Perhaps so interested as to even offer a reward...' WHERE `word_id` = 172856; -- locales_quest - details : entry=13941
UPDATE `trans_words` SET `content_loc7`='Give Brann Bronzebeard the contents of the Coffer of Promise.' WHERE `word_id` = 188864; -- locales_quest - objectives : entry=28633
UPDATE `trans_words` SET `content_loc7`='Give Grent Direhammer the closure he needs by killing Mauti.' WHERE `word_id` = 189844; -- locales_quest - objectives : entry=29115
UPDATE `trans_words` SET `content_loc7`='Give me a minute and I\'ll combine the essences into Fel fire.' WHERE `word_id` = 142186; -- locales_quest - offerrewardtext : entry=7602
