UPDATE `trans_words` SET `content_loc7`='Go to Gahrron\'s Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.' WHERE `word_id` = 183306; -- locales_quest - objectives : entry=27053
UPDATE `trans_words` SET `content_loc7`='Go to Orgrimmar\'s Drag and speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the cult, then put on your Recruit\'s Robe.' WHERE `word_id` = 171818; -- locales_quest - objectives : entry=25288
UPDATE `trans_words` SET `content_loc7`='Go to Shadowfang Keep and obtain Godfrey\'s Crystal Scope, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.' WHERE `word_id` = 184348; -- locales_quest - objectives : entry=27395
