UPDATE `trans_words` SET `content_loc7`='Go to the tower the slave spoke of. You should find it on the northeastern end of the camp.$B$BIf we can act fast enough we might be able to eavesdrop on the forgemaster\'s meeting.' WHERE `word_id` = 180454; -- locales_quest - details : entry=26260
UPDATE `trans_words` SET `content_loc7`='Go to the Upper Silvermarsh in Deepholm.' WHERE `word_id` = 183130; -- locales_quest - objectives : entry=27007
