UPDATE `trans_words` SET `content_loc7`='Help Elderlimb, Thisalee Crow, Tholo Whitehoof and Anren Shadowseeker escape the flames.' WHERE `word_id` = 190399; -- locales_quest - objectives : entry=29197
UPDATE `trans_words` SET `content_loc7`='Help Grandmatron Tekla' WHERE `word_id` = 176659; -- locales_quest - ObjectiveText1 : entry=25188
UPDATE `trans_words` SET `content_loc7`='Help has arrived at last!' WHERE `word_id` = 177098; -- locales_quest - offerrewardtext : entry=25320
UPDATE `trans_words` SET `content_loc7`='Help Kingslayer Orkus get out of the water.' WHERE `word_id` = 187901; -- locales_quest - objectives : entry=28345
UPDATE `trans_words` SET `content_loc7`='Help Malukaz Summon the Wolf Spirit' WHERE `word_id` = 152348; -- locales_quest - ObjectiveText2 : entry=10791
UPDATE `trans_words` SET `content_loc7`='Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un\'Goro Crater.' WHERE `word_id` = 175334; -- locales_quest - objectives : entry=24707
UPDATE `trans_words` SET `content_loc7`='Help Maximillian of Northshire slay 15 "Dragons".' WHERE `word_id` = 175318; -- locales_quest - objectives : entry=24704
UPDATE `trans_words` SET `content_loc7`='Help me, $C! Piggy men come burn stables - fire! Fire!$B$B<Dorak wails incoherently before you can settle him down.>$B$BWolves still chained inside. Someone\'s got to save the wee wolves!' WHERE `word_id` = 172667; -- locales_quest - details : entry=13878
UPDATE `trans_words` SET `content_loc7`='Help me, stranger. I must... reach Tranquillien... I cannot fail.$B$B<The blood elf falls back into unconsciousness as his eyes go blank.>' WHERE `word_id` = 146300; -- locales_quest - offerrewardtext : entry=9144
UPDATE `trans_words` SET `content_loc7`='Help Naralex seal the Nightmare Scar.' WHERE `word_id` = 175031; -- locales_quest - objectives : entry=24601
UPDATE `trans_words` SET `content_loc7`='Help out a fellow swabbie?$B$BKeelhaul asked me to gather up some cannonballs at the bottom of the ocean. Let me tell you why this doesn\'t work for me.$B$B- One: I have tiny arms. Look at them!  Do you really think I can pick up a cannonball, even underwater?$B$B- Two: I have a weak respiratory system. I start to white out after holding my breath for more than ten seconds.$B$B- Three: There are sharks.$B$BYou gotta help me, $N!  I\'ve been demoted as far as I can... I don\'t want to see what comes next!' WHERE `word_id` = 181788; -- locales_quest - details : entry=26635
UPDATE `trans_words` SET `content_loc7`='Help Patches kill Doctor Sabnok' WHERE `word_id` = 162818; -- locales_quest - ObjectiveText2 : entry=13152
UPDATE `trans_words` SET `content_loc7`='Help Raggaran' WHERE `word_id` = 176660; -- locales_quest - ObjectiveText2 : entry=25188
UPDATE `trans_words` SET `content_loc7`='Help Salhet defeat Bloodsnarl Hyenas' WHERE `word_id` = 187348; -- locales_quest - ObjectiveText1 : entry=28210
UPDATE `trans_words` SET `content_loc7`='Help Salhet slay 8 Bloodsnarl Hyenas.' WHERE `word_id` = 187345; -- locales_quest - objectives : entry=28210
UPDATE `trans_words` SET `content_loc7`='Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders.' WHERE `word_id` = 179318; -- locales_quest - objectives : entry=25932
UPDATE `trans_words` SET `content_loc7`='Help Tenjiyu' WHERE `word_id` = 180837; -- locales_quest - ObjectiveText2 : entry=26362
UPDATE `trans_words` SET `content_loc7`='Help the Crimson Lasher Drink from Ember Pools' WHERE `word_id` = 190687; -- locales_quest - ObjectiveText1 : entry=29299
UPDATE `trans_words` SET `content_loc7`='Help the Earthen Geomancers to get out of combat and then give them the Rockslide Reagents so that they can seal the Armory, Inn, Barracks, and Shrine.' WHERE `word_id` = 181277; -- locales_quest - objectives : entry=26501
UPDATE `trans_words` SET `content_loc7`='Help the inhabitants of the Craftsmen\'s Terrace and Tradesmen\'s Terrace make rice flour by pounding the contents of Rice Baskets.' WHERE `word_id` = 190200; -- locales_quest - objectives : entry=29316
UPDATE `trans_words` SET `content_loc7`='Help the inhabitants of Thunder Bluff make cornmeal by pounding bowls of Corn Kernels.' WHERE `word_id` = 190375; -- locales_quest - objectives : entry=29364
UPDATE `trans_words` SET `content_loc7`='Help Thrall break out of his stone prison' WHERE `word_id` = 190741; -- locales_quest - ObjectiveText1 : entry=29329
UPDATE `trans_words` SET `content_loc7`='Help us, $C! The forest is aflame, and the wee animals can\'t find their way out. They can\'t fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They\'re fluffy and sweet.$B$BThey have wet little noses!$B$BIf you don\'t save them, I don\'t want to even THINK about it.$B$B<She slaps her palms over her eyes.>$B$BI\'m not thinking!' WHERE `word_id` = 177291; -- locales_quest - details : entry=25385
UPDATE `trans_words` SET `content_loc7`='Help you? Help these people? These people that would rather spit on me than crack a smile?' WHERE `word_id` = 181528; -- locales_quest - offerrewardtext : entry=26567
UPDATE `trans_words` SET `content_loc7`='Help Zen\'Taji' WHERE `word_id` = 176662; -- locales_quest - ObjectiveText4 : entry=25188
UPDATE `trans_words` SET `content_loc7`='HELP! HELP! Crazed undead are attacking my farm! That psycho warden over at the Sludge Fields is probably responsible for this mess. Help me fight off the zombies!' WHERE `word_id` = 189130; -- locales_quest - details : entry=28733
UPDATE `trans_words` SET `content_loc7`='Help! Please help!' WHERE `word_id` = 187976; -- locales_quest - offerrewardtext : entry=28362
UPDATE `trans_words` SET `content_loc7`='Help... blood elves! They... ambushed... me. Don\'t have... long.' WHERE `word_id` = 146642; -- locales_quest - offerrewardtext : entry=9309
UPDATE `trans_words` SET `content_loc7`='Helpless Villager Rescued' WHERE `word_id` = 159133; -- locales_quest - ObjectiveText1 : entry=12237
UPDATE `trans_words` SET `content_loc7`='Helpless Young Druid Rescued' WHERE `word_id` = 179131; -- locales_quest - ObjectiveText1 : entry=25889
UPDATE `trans_words` SET `content_loc7`='Hemet Nesingwary Jr. doubted you, but his doubts were unfounded. You are absolutely destroying these raptors.' WHERE `word_id` = 165797; -- locales_quest - offerrewardtext : entry=195
UPDATE `trans_words` SET `content_loc7`='Hemet\'s taste test' WHERE `word_id` = 160598; -- locales_quest - ObjectiveText1 : entry=12645
UPDATE `trans_words` SET `content_loc7`='Her eye looks as if it is still alive. Do you think that she can still see into your soul?$B$B$N, you can now count yourself as one of the elite safari hunters. And you are another step closer to stalking the ultimate prey of this land, Tusker!$B$BYou\'ve earned the right to have this. May it serve you well.' WHERE `word_id` = 148688; -- locales_quest - offerrewardtext : entry=9856
UPDATE `trans_words` SET `content_loc7`='Herald Volazj Defeated' WHERE `word_id` = 162974; -- locales_quest - ObjectiveText2 : entry=13187
UPDATE `trans_words` SET `content_loc7`='Herald\'s Incense Burned' WHERE `word_id` = 178787; -- locales_quest - ObjectiveText1 : entry=25807
UPDATE `trans_words` SET `content_loc7`='Herbs Used in Flasks or Elixirs' WHERE `word_id` = 189543; -- locales_quest - ObjectiveText1 : entry=29067
UPDATE `trans_words` SET `content_loc7`='Here are some Cenarion plant salves - I only need one lesser nether essence for this, $N. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!' WHERE `word_id` = 138756; -- locales_quest - offerrewardtext : entry=4107
UPDATE `trans_words` SET `content_loc7`='Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!$B$BPlease, $N, take your pick!' WHERE `word_id` = 136096; -- locales_quest - offerrewardtext : entry=1682
UPDATE `trans_words` SET `content_loc7`='Here are the patterns, $N. I am sure you will find the product of this knowledge quite beautiful.' WHERE `word_id` = 144483; -- locales_quest - offerrewardtext : entry=8878
UPDATE `trans_words` SET `content_loc7`='Here are the wands I made. Take your pick!' WHERE `word_id` = 136521; -- locales_quest - offerrewardtext : entry=1952
UPDATE `trans_words` SET `content_loc7`='Here are your legguards, $N. Let me know how they fit or if you need any modifications. I aim to please! At least I used to.$B$BThese days I don\'t care much for my craft. But it beats being a mindless minion of the Scourge!$B$BI guess.' WHERE `word_id` = 136385; -- locales_quest - offerrewardtext : entry=1847
UPDATE `trans_words` SET `content_loc7`='Here are your robes, $N. Wear them well.' WHERE `word_id` = 136560; -- locales_quest - offerrewardtext : entry=1962
UPDATE `trans_words` SET `content_loc7`='Here goes nothing, $N! This will get Larion\'s attention!' WHERE `word_id` = 138849; -- locales_quest - offerrewardtext : entry=4144
UPDATE `trans_words` SET `content_loc7`='Here here, WOT!? He calls ME a COWARD!? Just like a Firebeard, all hot air and not a lick of sense. I\'ve been bearing the brunt of a Dragonmaw invasion from the south, much of Thundermar is in ruins, and do any of the other clans stick up to help? NO! Ol\' Thundermar is on his own he is, and you\'d better believe I\'m usin\' everything in my arsenal just to stem the tide.' WHERE `word_id` = 186561; -- locales_quest - offerrewardtext : entry=28001
UPDATE `trans_words` SET `content_loc7`='Here in Ironforge, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.' WHERE `word_id` = 136016; -- locales_quest - offerrewardtext : entry=1645
UPDATE `trans_words` SET `content_loc7`='Here in Marshal\'s Stand, I can\'t really do too much profiteering without arousing suspicion from the scientists. There is, however, another place where I might have use of you.$B$BMy business associate, Gremix, has a camp northwest of here, on the opposite side of the volcano. He\'s a savvy business mind, and has a better eye for profit than even I do. I\'m sure he could put you to work, if you\'d like to make some more coin.' WHERE `word_id` = 175268; -- locales_quest - details : entry=24693
UPDATE `trans_words` SET `content_loc7`='Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.' WHERE `word_id` = 136005; -- locales_quest - offerrewardtext : entry=1641
UPDATE `trans_words` SET `content_loc7`='Here is Ruag\'s report, $N. Let him know his scout is still here.$B$BDo not speak of Helgrum. I will not distract others with news of tragedy.$B$BI have to be strong. We all have to be strong.' WHERE `word_id` = 186213; -- locales_quest - details : entry=27916
UPDATE `trans_words` SET `content_loc7`='Here is the antidote, $N. Take it to Rhinag as soon as you can, and be cautious.' WHERE `word_id` = 133571; -- locales_quest - offerrewardtext : entry=813
UPDATE `trans_words` SET `content_loc7`='Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers. Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve. And around its frame, still in superior condition, is a Brigadier\'s Vest.$B$BThis grisly scene must have been where the Siege Engine pilot met his end.' WHERE `word_id` = 269748; -- locales_quest - offerrewardtext : entry=26854
UPDATE `trans_words` SET `content_loc7`='Here is your Dalaran Jewelcrafter\'s Token as promised. Come back tomorrow and I am sure I will have another item I need from you!' WHERE `word_id` = 161958; -- locales_quest - offerrewardtext : entry=12958
UPDATE `trans_words` SET `content_loc7`='Here is your Dalaran Jewelcrafter\'s Token as promised. I have new shipments going out all the time, check by from time to time to see what I need.' WHERE `word_id` = 162298; -- locales_quest - offerrewardtext : entry=13041
UPDATE `trans_words` SET `content_loc7`='Here is your first Gnome Engineer Membership Card!$B$BThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity. When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.$B$BThis never affects what you already know; once a gnome engineer, always a gnome engineer.' WHERE `word_id` = 138399; -- locales_quest - offerrewardtext : entry=3641
UPDATE `trans_words` SET `content_loc7`='Here is your first Goblin Engineer Membership Card!$B$BThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity. When it does, pay your next set of dues to any goblin engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.$B$BThis never affects what you already know; once a goblin engineer, always a goblin engineer.' WHERE `word_id` = 138391; -- locales_quest - offerrewardtext : entry=3639
UPDATE `trans_words` SET `content_loc7`='Here is your nether-lace, $N. It is both comfortable and durable, and holds the magic of the laughing sisters\' hair.$B$BEnjoy, and if you find it amenable, please mention so to Deino. She is a mage on whose good side I wish to stay...' WHERE `word_id` = 136494; -- locales_quest - offerrewardtext : entry=1946
UPDATE `trans_words` SET `content_loc7`='Here is your order, $N. Delivered as promised!' WHERE `word_id` = 145242; -- locales_quest - offerrewardtext : entry=9234
UPDATE `trans_words` SET `content_loc7`='Here is your payment ... and while you\'re here, take a look around! I\'m sure we have a potion or other trinket you\'d find useful.' WHERE `word_id` = 130380; -- locales_quest - offerrewardtext : entry=61
UPDATE `trans_words` SET `content_loc7`='Here is your robe. It\'s one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!' WHERE `word_id` = 136476; -- locales_quest - offerrewardtext : entry=1941
UPDATE `trans_words` SET `content_loc7`='Here is your schematic. Study it closely, and learn...$B$BGood luck, $N. May your celebrations rival that of the Lunar Festival itself!' WHERE `word_id` = 144491; -- locales_quest - offerrewardtext : entry=8882
UPDATE `trans_words` SET `content_loc7`='Here it is - the Hand of Iruxos.$B$BGot it from one o\' them Burning Blade leaders myself.$B$BPowerful thing! See, yeh use it on demon portals and they just disappear! Spooky magic, but these be desperate times....$B$BThe demons keep comin\' at this rate, and my camp will get overrun before ya know it.$B$BHere ya go, now. Get on with it.' WHERE `word_id` = 275192; -- locales_quest - details : entry=14374
UPDATE `trans_words` SET `content_loc7`='Here it is, $N, the proof of my crime. This journal contains all of my ill-conceived studies.$B$BHeedless of the warnings, I continued my research, until it was almost too late. Then, when I grasped my error, I did what I could. But by then, some of my pupils had already gone too far. I evacuated the Spire to get them away from the corruption, but in my haste, forgot to shutdown the power sources.$B$BI will burn this tome so that no one else falls prey to its contents. I only wanted to help the sin\'dorei.' WHERE `word_id` = 146175; -- locales_quest - offerrewardtext : entry=8891
UPDATE `trans_words` SET `content_loc7`='Here it is, $N. A weapon worthy of a champion of the Light such as yourself. I\'ve named it after a great dwarven paladin who was a friend of mine. His name was Verigan... Bosch Verigan.$B$BPlease take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land.' WHERE `word_id` = 136319; -- locales_quest - offerrewardtext : entry=1806
UPDATE `trans_words` SET `content_loc7`='Here it is, $N. Remember, ya have ta carry it with you. Why don\'t ya head back to da wilds, an\' see what ya be findin\' there?' WHERE `word_id` = 166751; -- locales_quest - offerrewardtext : entry=975
UPDATE `trans_words` SET `content_loc7`='Here it is, $N. Use it well in the service of Silvermoon and your order.' WHERE `word_id` = 148056; -- locales_quest - offerrewardtext : entry=9710
UPDATE `trans_words` SET `content_loc7`='Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren\'s body is broken, lying in a pool of his own blood.$B$BA trail of droplets leads back to the inn....' WHERE `word_id` = 179059; -- locales_quest - details : entry=25873
UPDATE `trans_words` SET `content_loc7`='Here now. Ye hear that? There be sounds in them hills. Those\'re the wolpertingers! Wily beasts, they are, attracted by the smells o\' Brewfest. I\'ve a mind to catch me some, but I knocked me shin and can\'t outrun the buggers. Ye can help me, though!$B$BTake this net and cast it over the little blighters. Bring me a good five of \'em and I\'ll make it worth yer while! Oh, and one more thing - in order to even see these critters, ye need t\' be blitzed! Load up on the booze!' WHERE `word_id` = 153700; -- locales_quest - details : entry=11117
UPDATE `trans_words` SET `content_loc7`='Here so soon! Lovely trip I hope. Not too nauseous or anything? There will be much running and much jumping, so a settled stomach is of great practicality.' WHERE `word_id` = 174303; -- locales_quest - offerrewardtext : entry=14413
UPDATE `trans_words` SET `content_loc7`='Here the Guardian Medivh feverishly works to open the Dark Portal.$B$BScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh\'s shields and, ultimately, Medivh.$B$BKill their rift lords and leaders until Medivh succeeds!' WHERE `word_id` = 191311; -- locales_quest - details : entry=29672
UPDATE `trans_words` SET `content_loc7`='Here they come, $N! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!$B$BTake wing once more, $C, and slay them.$B$BRun into enemy riders with your lance to destroy them.$B$BGo forth. Fly, fool. Fly!' WHERE `word_id` = 177740; -- locales_quest - details : entry=25525
UPDATE `trans_words` SET `content_loc7`='Here to get in on the bounty action, eh?' WHERE `word_id` = 158991; -- locales_quest - offerrewardtext : entry=12208
UPDATE `trans_words` SET `content_loc7`='Here to help with the clam diving?$B$BGet to it then. There are clams about everywhere just waiting to be dived.' WHERE `word_id` = 177781; -- locales_quest - details : entry=25539
UPDATE `trans_words` SET `content_loc7`='Here we are deep within the realm of the fire god and what do we find? The little puppets of Ragnaros, scurrying around to do his bidding.$B$BThese Dark Iron laborers are finishing and packaging the weapons Twilight\'s Hammer hopes to use in their conquest of Hyjal. I don\'t care if they\'re here of their own free will or if they\'ve been brainwashed or kidnapped... They\'re a foe of our beloved Wolf Ancient and they should pay the ultimate price.' WHERE `word_id` = 177898; -- locales_quest - details : entry=25576
UPDATE `trans_words` SET `content_loc7`='Here we are, $N! Great things will happen here... magical things!' WHERE `word_id` = 187613; -- locales_quest - offerrewardtext : entry=28274
UPDATE `trans_words` SET `content_loc7`='Here we are, $N. He is a little rotted, but no worse for the wear. We must hurry before the Alliance finds us!' WHERE `word_id` = 184384; -- locales_quest - offerrewardtext : entry=27406
UPDATE `trans_words` SET `content_loc7`='Here we are, mortal.$B$BThe rift emits intense energy that will shield the magic of your artifact.$B$BWhen you are ready, I will activate the Eye. Doing so will require all of my focus. You must witness the vision on your own.$B$BHurry now, $C. It is unsafe for us to tarry here.' WHERE `word_id` = 190470; -- locales_quest - details : entry=29224
UPDATE `trans_words` SET `content_loc7`='Here we go, $N!$B$BJust beyond that door lies the control room.$B$BI\'ll just run in, disable the reorigination mechanism, and then we all go home. Nice an\' easy.$B$BYe see, $Glad:lass;, it\'s this level of preparation that separates yer true archaeologist from yer average treasure hunter.$B$BNo sense in stirring up the beasties if ye don\'t have to. Just makes a mess a\' things...' WHERE `word_id` = 189173; -- locales_quest - details : entry=28746
UPDATE `trans_words` SET `content_loc7`='Here ya go $N - put this thing on, and you\'ll have ten minutes to do whatever. Good luck!$B$BOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!' WHERE `word_id` = 140413; -- locales_quest - offerrewardtext : entry=27120
UPDATE `trans_words` SET `content_loc7`='Here you are, $C. With this you should find maneuvering in the sea to be nearly effortless. $B$BNow we must get to work. There is much to be done in little time.' WHERE `word_id` = 174554; -- locales_quest - offerrewardtext : entry=24432
UPDATE `trans_words` SET `content_loc7`='Here you are, $N. Here are Darkmoon Faire tickets for your enjoyment. Do not, as they say, spend them all in one place!' WHERE `word_id` = 142714; -- locales_quest - offerrewardtext : entry=7942
UPDATE `trans_words` SET `content_loc7`='Here you are, $N. Here is the schematic to create a firework launcher. Place launchers where you wish to celebrate, and then welcome your friends to join you!' WHERE `word_id` = 144481; -- locales_quest - offerrewardtext : entry=8877
UPDATE `trans_words` SET `content_loc7`='Here you are, $N. I will now give ya the power to tame a beast, as well as call it and dismiss it as you please.$B$BFind yerself a good, loyal pet, and enjoy the hunt!' WHERE `word_id` = 140972; -- locales_quest - offerrewardtext : entry=6085
UPDATE `trans_words` SET `content_loc7`='Here you are, $N. One more Twilight medallion of station. Use it well, and I wish you luck against the Abyssal Council!' WHERE `word_id` = 143332; -- locales_quest - offerrewardtext : entry=8333
UPDATE `trans_words` SET `content_loc7`='Here you are, $N. Take these recipes and learn their secrets. I bid you fortune, and I look forward to seeing your magnificent creations.' WHERE `word_id` = 144487; -- locales_quest - offerrewardtext : entry=8880
UPDATE `trans_words` SET `content_loc7`='Here you go, $N. And please tell Menara we say hello.$B$BWe expect great things of you. Perhaps when the Legion falls to its knees, your name will be spoken aloud and in praise of your power. I can\'t wait!' WHERE `word_id` = 139426; -- locales_quest - offerrewardtext : entry=4785
UPDATE `trans_words` SET `content_loc7`='Here you go, $N. Try these on.' WHERE `word_id` = 133211; -- locales_quest - offerrewardtext : entry=716
UPDATE `trans_words` SET `content_loc7`='Here you go, as promised! One Boulder-in-a-Box.$B$BLilith was asking for this, wasn\'t she? She\'s my only customer!' WHERE `word_id` = 188805; -- locales_quest - details : entry=28618
UPDATE `trans_words` SET `content_loc7`='Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!$B$BIf you have more tickets you\'d like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I\'ll redeem your tickets.' WHERE `word_id` = 146522; -- locales_quest - offerrewardtext : entry=9249
UPDATE `trans_words` SET `content_loc7`='Here you go, here you go! A prize fit for a $Gking:queen;! Congratulations to you, my friend!$B$BIf you have more tickets you\'d like to turn in, then please let me know! For as long as the Darkmoon Faire is here, I\'ll redeem your tickets.' WHERE `word_id` = 142690; -- locales_quest - offerrewardtext : entry=7930
UPDATE `trans_words` SET `content_loc7`='Here you go, one instant Super-Gro Insta-Tree made with 80%natural ingredients!$B$BNo roots, no muss, no fuss. Just give it to Kilram and make sure he stands the heck back when he uses it.' WHERE `word_id` = 188836; -- locales_quest - details : entry=28626
UPDATE `trans_words` SET `content_loc7`='Here, let me read those plans.$B$BThe blood elves have followed us here?  They are evil to the core and should be wiped from existence!$B$B<The vindicator takes a moment to regain his composure.>$B$BI apologize, that was uncalled for. We are indebted to you for uncovering this information, $N.' WHERE `word_id` = 148420; -- locales_quest - offerrewardtext : entry=9798
UPDATE `trans_words` SET `content_loc7`='Here, take some coin... get yerself... <hic>... some new armor or something....$B$BThis\'ll bring a shiny gold or two to the right... <hic> people.' WHERE `word_id` = 138285; -- locales_quest - offerrewardtext : entry=3542
UPDATE `trans_words` SET `content_loc7`='Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.$B$BCongrats, $N. You\'re a parent... kinda.' WHERE `word_id` = 139045; -- locales_quest - offerrewardtext : entry=4298
UPDATE `trans_words` SET `content_loc7`='Here\'s another favor you can do for me, pal.$B$BWe had a whole shipment of Landmines come in from Booty Bay just the other day. But someone stole the whole lot of \'em in the night!$B$BWhoever it was must be sloppy, because they dropped them all over the swamp to the east. No goblin I know would be that careless.$B$BI need you to go gather those landmines up for me. I\'m sure they\'re perfectly safe and disarmed. Every single one. Yup.' WHERE `word_id` = 184868; -- locales_quest - details : entry=27536
UPDATE `trans_words` SET `content_loc7`='Here\'s my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare.' WHERE `word_id` = 138122; -- locales_quest - offerrewardtext : entry=3451
UPDATE `trans_words` SET `content_loc7`='Here\'s the deal, kid, we\'ve got a full-blown murder on our hands. Double homicide... Single horse... icide.$B$BWorse yet, we\'re in Westfall. I could throw a rock behind me and hit a dozen hobos with motive enough to want to wipe these people (and horse) out.$B$BNow I don\'t know who did this and I sure don\'t appreciate having to come to this dump to investigate the deaths of a couple of squatters, but I\'ll be damned if I don\'t find the perp. You want to help? Go talk to some bums. The hobo... knows.' WHERE `word_id` = 180267; -- locales_quest - details : entry=26209
UPDATE `trans_words` SET `content_loc7`='Here\'s the deal, mate: to protect me treasure map, I tattooed it onto me first mate\'s scalp.$B$BOf course, he\'s dead now, along with most of me crew. The Alliance doesn\'t even know what they have - his severed head is hanging from a tree at the entrance to this camp.$B$BGrab that head and take it to Gazlowe back in Ratchet.' WHERE `word_id` = 173183; -- locales_quest - details : entry=14049
UPDATE `trans_words` SET `content_loc7`='Here\'s the dilemma: I could do one of two things, get killed down here like everyone else or get killed up at Krom\'gar Fortress when Krom\'gar realizes we\'ve lost the mine. I\'m choosing the third option, do nothing. So far, so good.$B$BYou need parts? Plenty from the left over junk scattered about in this mine. You just gotta go get \'em.$B$BGood luck! Maybe if you get those parts we might be able to show our faces at Krom\'gar Fortress.' WHERE `word_id` = 179691; -- locales_quest - details : entry=26045
UPDATE `trans_words` SET `content_loc7`='Here\'s the situation. If we want to establish the Bilgewater Cartel\'s market presence in Gadgetzan, we\'ll need to start providing services to the community.$B$BThe new coast has been great for business here, but the sea also brought sea giants with it. They\'re large, foul, and drive real estate values down.$B$BHead to the shallows just south of town and kill as many as you can, and I\'ll cut you in on some of the deals I\'m brokering here.' WHERE `word_id` = 175606; -- locales_quest - details : entry=24907
UPDATE `trans_words` SET `content_loc7`='Here\'s to hopin\' those treacherous bilge rats learned their lessons! Now it be time to man the big\'un, matey!' WHERE `word_id` = 156807; -- locales_quest - offerrewardtext : entry=11527
UPDATE `trans_words` SET `content_loc7`='Here\'s what you\'re looking for: Trelane\'s phylactery, Trelane\'s orb, and Trelane\'s ember agate.$B$BAll three should be in chests within the tower. You shouldn\'t have a problem opening the chests on your own; you just have to be careful of the ogres.$B$BYou\'ll need to have your weapons at the ready. Those ogres find out you\'re there and stealing from them, and they\'ll be sure to put the hurt on you.$B$BBe careful, and good luck.' WHERE `word_id` = 179676; -- locales_quest - details : entry=26038
UPDATE `trans_words` SET `content_loc7`='Here\'s your armor, $N. Furen\'s process worked brilliantly! Perfectly! Marvelously, truly!$B$BYou could run this armor over with a siege engine and it would spring right back into shape!' WHERE `word_id` = 136188; -- locales_quest - offerrewardtext : entry=1709
UPDATE `trans_words` SET `content_loc7`='Here\'s your armor, $N. This will stand up to the strongest assaults or my name isn\'t Furen Longbeard!$B$BAnd I have to thank you. I learned a lot while working with the materials$Byou brought me. I think I\'ll have another breakthrough one day!$B$BI\'m going to send what I learned to other$Bblacksmiths of the Alliance.$B$BI\'ll tell them you were a big help, and maybe they\'ll want to return the favor.' WHERE `word_id` = 136248; -- locales_quest - offerrewardtext : entry=1782
UPDATE `trans_words` SET `content_loc7`='Here\'s your ring, better than before. Thanks again for the information about those Dark Iron dwarves. This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration.' WHERE `word_id` = 137537; -- locales_quest - offerrewardtext : entry=2950
UPDATE `trans_words` SET `content_loc7`='Hero, listen well.$B$BFirst, we must travel to the Deathly Usher, who waits at the northern foot of the Rise of the Defiler, to our northeast. The usher will take us to the top of the rise. Once there, I need you to help me defeat Razelikh, for I fear that I am not strong enough to defeat him alone.$B$BMost importantly, I need you to hold the stone knife, and do not use it until I tell you to. The knife will trap Razelikh\'s soul within its new, eternal prison.$B$BIf we succeed, speak with Wazzik.' WHERE `word_id` = 178397; -- locales_quest - details : entry=25701
UPDATE `trans_words` SET `content_loc7`='Hero, listen well.$B$BFirst, we must travel to the Deathly Usher, who waits at the northern foot of the Rise of the Defiler, to our northwest. The usher will take us to the top of the rise. Once there, you will help me defeat Razelikh, for I fear I am not strong enough to defeat him alone.$B$BMost importantly, I need you to hold the stone knife, and do not use it until I tell you to. The knife will trap Razelikh\'s soul within its new, eternal prison.$B$BIf we succeed, speak with Grimeo, the draenei.' WHERE `word_id` = 180136; -- locales_quest - details : entry=26171
UPDATE `trans_words` SET `content_loc7`='Herod is slain! The Armory will fall!' WHERE `word_id` = 182951; -- locales_quest - offerrewardtext : entry=26962
UPDATE `trans_words` SET `content_loc7`='Heroes: If you are reading this, then my suspicions were correct. Deathwing has found us. The egg is destroyed, as am I. This was, actually, the plan from the beginning. You see... the egg that Deathwing destroyed was not the egg he sought. It was mine.' WHERE `word_id` = 186277; -- locales_quest - offerrewardtext : entry=27930
UPDATE `trans_words` SET `content_loc7`='Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil.$B$BI try to keep a good supply of it because it\'s so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut\'theran Village.' WHERE `word_id` = 190350; -- locales_quest - details : entry=29359
UPDATE `trans_words` SET `content_loc7`='Hexascrub came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.$B$BHe\'s got an idea for another balloon, but we need to make sure that the past doesn\'t repeat itself. I need you to kill off those gill goblins. Or at the very least, enough of them to make them a bit more wary of us.' WHERE `word_id` = 179152; -- locales_quest - details : entry=25894
UPDATE `trans_words` SET `content_loc7`='Hey - you must be that $G fella\': lass; that Wulfred was talkin\' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north. Welcome to the digsite, $N!$B$BWe were actually working on identifying those samples right as you got here. Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.' WHERE `word_id` = 182450; -- locales_quest - details : entry=26825
UPDATE `trans_words` SET `content_loc7`='Hey - you must be that $G fella\': lass; that Wulfred was talkin\' about!  Welcome to the digsite, $N.$B$BWe were actually just starting a project when you arrived. Would you mind bringing this sample over to Dask?  I need him to help me find out how old it is.' WHERE `word_id` = 182454; -- locales_quest - details : entry=26826
UPDATE `trans_words` SET `content_loc7`='Hey $G bub: sweetie;, interested in making an extra dime?$B$BI\'ve got it on good authority that some interested parties are paying BIG money for silithid legs. Yes, you heard me right, silithid legs!  Apparently these things are delicious if you cook them right. They\'re like underground lobsters, and they live just south of here.$B$BThing is, I\'ll need a good amount of them to pay for my overhead. Think you could get me 8 dozen or so?' WHERE `word_id` = 175259; -- locales_quest - details : entry=24691
UPDATE `trans_words` SET `content_loc7`='Hey $N, do you see this footprint? We found them all over the camp last night! Nothing\'s missing, but all our belongings have been...examined. The muddy trails lead back toward the Sludge Fen.$B$BSomeone\'s been sniffing around, and I don\'t like it one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more tracks just like this one!' WHERE `word_id` = 189742; -- locales_quest - details : entry=29087
UPDATE `trans_words` SET `content_loc7`='Hey $N, we\'ve got a real problem here. There\'s an overpopulation of hyenas just west of the Sludge Fen, and they\'re starting to become a menace.$B$BIf I have to listen to them caterwauling one more night, I just might go crazy! Vernon over there says the hyenas might even have made off with one of his stabled pigs. We can\'t have that happening.$B$BCan you go thin out the hyena numbers? You\'ll find them parading in broad daylight to the west.' WHERE `word_id` = 189747; -- locales_quest - details : entry=29088
UPDATE `trans_words` SET `content_loc7`='Hey bud! Like explosions? Of course you do. Who doesn\'t like explosions?!$B$BI\'ve got mortars set up on the ridge to the east to hold the naga back. Go forth, recruit. Mortar them... mortar them all! Ahahahah.' WHERE `word_id` = 174461; -- locales_quest - details : entry=14471
UPDATE `trans_words` SET `content_loc7`='Hey bud. Seeing as how you\'re so friendly and great and all, think you might do a dwarf a favor?$B$BThese are Dunwald ruins... there\'s SURE to be more stock in some of these buildings. If you come upon more ale, bring it my way, will ya? A good dwarf can never have enough!$B$BI\'m thinkin\' I\'ll find my way back to Keely, so ya might have to hunt me down, but I\'ll try\'n make it worth it to ya.' WHERE `word_id` = 185252; -- locales_quest - details : entry=27649
UPDATE `trans_words` SET `content_loc7`='Hey hey mon, did Dizzywig send you? Good, good. Did you bring the money? No? ...what about the guns?' WHERE `word_id` = 173195; -- locales_quest - offerrewardtext : entry=14052
UPDATE `trans_words` SET `content_loc7`='Hey hey!  Not bad, not bad at all!  You may have a future in resource acquisition. Or hotel management.' WHERE `word_id` = 181226; -- locales_quest - offerrewardtext : entry=26487
UPDATE `trans_words` SET `content_loc7`='Hey Hol\'anyee, look at the getup on this one! Ahem. Our recruiter sent you?  Good. Let\'s start out with a bit of honesty: Un\'Goro isn\'t the perfect nirvana that you may have been promised. You\'ve probably figured that out on the way over here, though. Shall we get to work?' WHERE `word_id` = 175624; -- locales_quest - offerrewardtext : entry=24911
UPDATE `trans_words` SET `content_loc7`='Hey mon, take a knee and hear me out. We got a problem.$B$BA good friend of mine, Hana\'zua, has gone out into the valley and he hasn\'t returned. Last I seen, he was headin\' north, where the scorpids hunt. Maybe you go take a look for him?  The spirits be tellin\' me that he\'s not well.' WHERE `word_id` = 176447; -- locales_quest - details : entry=25128
UPDATE `trans_words` SET `content_loc7`='Hey now, where ya be gettin\' this?$B$BNo, no, don\'t tell me - this be comin\' from the Hex-Lord himself! It all be clear now. Strong mojo! The bearer of this relic, no matter how many disgraces he be sufferin\', be always honored by his peers. Incredible!$B$B<As Griftah holds the doll in the air, a small, rusty charm falls from around its neck. The troll begins to discard it, but then turns toward you with a gleam in his eye.>$B$BI gots no coins right now, mon, but ya be welcome to this here...' WHERE `word_id` = 154002; -- locales_quest - offerrewardtext : entry=11195
UPDATE `trans_words` SET `content_loc7`='Hey pal! I\'m still working on a variant of a gnomish shrinking ray, using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I\'d like for you to try it out on some of the sea giants along the coast here. You should find miniaturization residue on them after you shrink them - bring me back some!' WHERE `word_id` = 177538; -- locales_quest - details : entry=25465
UPDATE `trans_words` SET `content_loc7`='Hey there $C, I need you to solve the Cataclysm. Go hunt me some zombies.' WHERE `word_id` = 174648; -- locales_quest - details : entry=24460
UPDATE `trans_words` SET `content_loc7`='Hey there!  I\'m a crazy dwarf!  We dwarves believe when you get enough brew together, invisible creatures show up. In fact they are probably wandering around the Brewfest grounds right now! But you can only see them if you are really drunk.$B$BWe dwarves will come up with any excuse to drink.$B$BI bet you want a reason to drink too... So here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.$B$BIf you can\'t see them, you\'re probably not drunk enough.' WHERE `word_id` = 154339; -- locales_quest - details : entry=11431
UPDATE `trans_words` SET `content_loc7`='Hey there!  Interested in makin\' a buck?$B$BI need to get a bandage. Well, actually, I got a friend who needs to get a bandage. Well actually... let\'s just say it\'s complicated, but if you go get this bandage, you make money. And so do I. And my friend. Possibly other people.$B$BStephen Browman used to own the mill to the north, now he\'s dead. A zombie. The guy at the top wants to have the wrappings from Browman\'s body.$B$BWhat\'s the matter, you don\'t like money?' WHERE `word_id` = 184529; -- locales_quest - details : entry=27458
UPDATE `trans_words` SET `content_loc7`='Hey there! Step right up!$B$BWhy not show everyone how skilled you are?  Just land three rings on the Darkmoon Turtle and you\'ll get a prize.$B$BFor one game token you can buy a stack of rings and show the world why we call you the "Eagle Eyed $C."' WHERE `word_id` = 190935; -- locales_quest - details : entry=29455
UPDATE `trans_words` SET `content_loc7`='Hey there! Who are you?$B$BBixie sent you? Excellent, let\'s get me out of here!' WHERE `word_id` = 157415; -- locales_quest - offerrewardtext : entry=11697
UPDATE `trans_words` SET `content_loc7`='Hey there, $Glad:lass;. I\'m sure Keely\'s got you worrying about our brothers, but they can take care of themselves. They\'ll find their way back here one way or another.$B$BMaybe you can do me a favor while you\'re out meeting the family... Dunwald territory is still infested with Twilight\'s Hammer and their servants. I\'d appreciate it if you could remind them that they\'re not welcome.' WHERE `word_id` = 185215; -- locales_quest - details : entry=27641
UPDATE `trans_words` SET `content_loc7`='Hey there, $N. I\'m Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.$B$BI share your concerns about helping all of Thousand Needles. It\'s my firm belief that the Speedbarge is the best hope for the entire region.$B$BPerhaps you could help us out a little bit here? I\'ll make sure that you\'re equipped with what you need to tackle everything else.$B$BAs to that, if you could just run this list of parts over to Razzeric in his shop, you\'ll be well on your way.' WHERE `word_id` = 177661; -- locales_quest - details : entry=25505
UPDATE `trans_words` SET `content_loc7`='Hey there, Angler!  Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place. North of Stormwind there is a great little spot called Olivia\'s Pond.$B$BThe pond is stocked with crystal bass every year but they are hard to catch. They only bite on a very specific type of bait... overgrown earthworms. If you search the shore around the pond, you should find plenty of worms to use as bait.' WHERE `word_id` = 181071; -- locales_quest - details : entry=26420
UPDATE `trans_words` SET `content_loc7`='Hey there, buddy. Want to make a quick buck?$B$BBring me back any highborne tablets you find in the ruins.' WHERE `word_id` = 174520; -- locales_quest - details : entry=14486
UPDATE `trans_words` SET `content_loc7`='Hey there, hon. Vol\'jin sent you? So sweet of him to be thinkin\' of me. I surely could use da help, but ya have a bit more walkin\' ahead of ya.' WHERE `word_id` = 176207; -- locales_quest - offerrewardtext : entry=25064
UPDATE `trans_words` SET `content_loc7`='Hey there. I\'m glad to see they sent someone of your caliber for this operation. This here\'s going to call for some subtlety. We can\'t risk Commander Shadowsong getting killed.' WHERE `word_id` = 177987; -- locales_quest - offerrewardtext : entry=25597
UPDATE `trans_words` SET `content_loc7`='Hey there... again. Look, I gave you my hat. It was a gift. I thought you\'d make some use of it. More specifically though, I thought you\'d get it the heck away from me. Can you imagine my surprise when Xylem comes by himself to give it back to me? "Want to be more like my other apprentices, Sorata? Give your hat another try."  Not one of my proudest moments. So what... you just tossed it aside for him to find? No. I don\'t think so. You\'re going to take this hat and you\'re going to like it. Really.' WHERE `word_id` = 174216; -- locales_quest - offerrewardtext : entry=14392
UPDATE `trans_words` SET `content_loc7`='Hey wait a minute, this bone has pickax marks on it. These aren\'t yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!$B$BLet me step back for a minute and explain. There\'s another archaeologist south of here named Durrin Direshovel. He practices a reckless, devil-may-care brand of archaeology that offends even me.$B$BA priceless fossil, ruined by sloppy pick-work. This is the last straw, Durrin!$B$B$N, go put an end to Direshovel and his negligent excavation.' WHERE `word_id` = 175343; -- locales_quest - details : entry=24709
UPDATE `trans_words` SET `content_loc7`='Hey you! Good to see you again!$B$BI\'m settled in good and fine, actually! It\'s good to be with good old Damek again. I never thought I\'d be mixing with a dwarf so well, but he and I, we\'ve got like minds on all the important stuff.$B$BYou go do your thing. Don\'t be worrying about us. If we cook up any good toys for you, we\'ll be sure to let ya know!' WHERE `word_id` = 190620; -- locales_quest - offerrewardtext : entry=29282
UPDATE `trans_words` SET `content_loc7`='Hey! Get me out of here!' WHERE `word_id` = 177959; -- locales_quest - offerrewardtext : entry=25590
UPDATE `trans_words` SET `content_loc7`='Hey! I know you. Your victory at the Ring of Blood was talked about for months! Too bad you forfeited the championship when you failed to show up to defend your title! Easy come, easy go, eh? At least you\'re still alive.' WHERE `word_id` = 161933; -- locales_quest - offerrewardtext : entry=12954
UPDATE `trans_words` SET `content_loc7`='Hey! I need some help gatherin\' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I\'ll cut you in on the profits.$B$BUse these bombs to blow out chunks from the bigger formations.$B$BI\'ve got a nasty habit of packin\' the explosives a bit thick. Mind the kick.' WHERE `word_id` = 183285; -- locales_quest - details : entry=27048
UPDATE `trans_words` SET `content_loc7`='Hey! I\'m glad I caught you.$B$BI come on behalf of my master, Kalec. He requires your aid. Find him under the bridge in the slums as soon as you can!' WHERE `word_id` = 174280; -- locales_quest - details : entry=14407
UPDATE `trans_words` SET `content_loc7`='Hey! Wait just one damned minute!!$B$BThis doesn\'t look good...' WHERE `word_id` = 151956; -- locales_quest - offerrewardtext : entry=10674
UPDATE `trans_words` SET `content_loc7`='Hey, $C!$B$BAre you headed to support Corporal Teegan? He\'s in charge of keeping the supply routes open.$B$BHe\'s got two of the most ornery dwarves I\'ve ever met in charge of sundries. If you want to make an impression on those two crotchety hunters, you\'re going to need to show that you can hold your own against the predators around here.$B$BThe raptors west of the hold here are especially vicious. Bring Goucho some fresh hides and you\'ll make an impression while supplying the troops in one swoop.' WHERE `word_id` = 175956; -- locales_quest - details : entry=25000
UPDATE `trans_words` SET `content_loc7`='Hey, $N, I\'ve got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.$B$BWhat could possibly go wrong?$B$BReady to put it on?' WHERE `word_id` = 179507; -- locales_quest - details : entry=25987
UPDATE `trans_words` SET `content_loc7`='Hey, $N, you haven\'t seen my other brother, Wizzle, have you?$B$BI just know that the pirates captured him! He said that he was going to try to sell them some engineering stuff, or something.$B$BWould you please look for him up at the Southsea Holdfast to the east? I\'ll bet that no-good goblin he\'s always traveling with, Synge, got him into trouble!' WHERE `word_id` = 177957; -- locales_quest - details : entry=25590
UPDATE `trans_words` SET `content_loc7`='Hey, $N, you haven\'t seen our gunsmith, Synge, have you?$B$BI just know that the pirates captured him! He said that he was going to try to sell them some rifles, or something.$B$BWould you please look for him up at the Southsea Holdfast to the east? I\'ll bet that no-good gnome he\'s always traveling with, Wizzle Brassbolts, got him into trouble!' WHERE `word_id` = 177983; -- locales_quest - details : entry=25596
UPDATE `trans_words` SET `content_loc7`='Hey, $R, listen up. I got a job opportunity that you aren\'t gonna want to miss out on.$B$BWe been sent up here from Fuselight, a new goblin town way down in the Badlands. Lots of money to be had down there, yes $G sir: ma\'am;. And not nearly so many zombies... or uptight Argent paladin-types.$B$BNope, it\'s an untamed wilderness down there, and we\'re looking for someone like you to help us tame it. Whenever you\'re ready... we\'ll be waiting.' WHERE `word_id` = 185670; -- locales_quest - details : entry=27762
UPDATE `trans_words` SET `content_loc7`='Hey, friend, you interested in excitement? Adventure? Money? Violence?$B$BWell, you\'d better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it\'s back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!$B$BHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!' WHERE `word_id` = 182700; -- locales_quest - details : entry=26895
UPDATE `trans_words` SET `content_loc7`='Hey, have you been to Hardwrench Hideaway yet?  Oh, you\'ve GOT to see it. It\'s everything a goblin could ever hope for.$B$BTell you what... you look like a stand-up $C. Raskha in the vest and the skirt over here can give you a ride, if you don\'t already know the way.$B$BThe flight\'s on me.' WHERE `word_id` = 181008; -- locales_quest - details : entry=26404
UPDATE `trans_words` SET `content_loc7`='Hey, I know!  We\'ve been looking at the wrong tar creatures.$B$BGremix once told me about a larger-than-normal tar creature that he ran into. It lurks around the tar pit far to the east of here, south of Fungal Rock. I\'ll bet that the bigger these creatures get, the stickier they get!  We\'ll make some money yet, $N!$B$BDon\'t forget the scraper!' WHERE `word_id` = 175294; -- locales_quest - details : entry=24699
UPDATE `trans_words` SET `content_loc7`='Hey, is that what I think it is? Great!$B$BNow, let\'s see. Ugh... how am I supposed to understand this stuff... can\'t figure out the way gnomes think. Lemme tell you, I\'m surprised they could build the wheel, let alone those flying machines they like so much.' WHERE `word_id` = 134722; -- locales_quest - offerrewardtext : entry=1093
UPDATE `trans_words` SET `content_loc7`='Hey, it\'s you again! Well, I mean you - as in the you that is $N! Yes - that you!$B$BHey, let me start over!$B$BThat object you found in Silithus - it was in fact a book. It was a journal written in a very ancient dialect of what we now call the Darnassian tongue. It\'ll take a while, but I\'m going to go over it very thoroughly. I thought you should know that what you found was extremely valuable for the Circle.$B$BThe den mother\'s all excited and everything!' WHERE `word_id` = 135076; -- locales_quest - offerrewardtext : entry=1185
UPDATE `trans_words` SET `content_loc7`='Hey, listen. You don\'t look like any old tourist, and I\'m in a bit of a pickle. My cousin up north sent me this weird artifact, and I need your help to... ah... identify it.$B$BTo start out, I\'m going to need you to obtain The Holy Water of Clarity. Rumor has it that whoever drinks from this spring is given a vision of clarity.$B$BSounds pretty promising, doesn\'t it?$B$BObtain it from the Nek\'mani Wellspring at the peak of the naga camp. Good luck!' WHERE `word_id` = 181627; -- locales_quest - details : entry=26590
UPDATE `trans_words` SET `content_loc7`='Hey, look at how glowy it is!$B$B<Orako looks wistfully off into the distance.>$B$BMy wolf loved things that were glowy...' WHERE `word_id` = 179849; -- locales_quest - offerrewardtext : entry=26087
UPDATE `trans_words` SET `content_loc7`='Hey, look at that!  You weren\'t blown to bits!' WHERE `word_id` = 165390; -- locales_quest - offerrewardtext : entry=25285
UPDATE `trans_words` SET `content_loc7`='Hey, mon! Thank ya for comin\'.$B$BWe weren\'t ready for dis kind of attack. We been expectin\' da Twilight Cult, but not elementals... we\'ve got no idea what upset dem so much that dey would turn on us like dis.$B$BYou haven\'t been out dere killin\' them, have you?' WHERE `word_id` = 180712; -- locales_quest - offerrewardtext : entry=26326
UPDATE `trans_words` SET `content_loc7`='Hey, new $G guy: girl;, take a look at this.$B$B<The dwarf flips up his eyepatch to reveal a living, functional eyeball.>$B$BI don\'t wear this patch because of any lost eye. I wear it because this OTHER eye is so strong, the normal one was just weighin\' it down.$B$BThis eye\'s good for seein\' all kinds of things, like those masked hooligans that follow us around. Fleet Master says that they\'ve been spotted over on Jaguero Isle. Once you get there, fire this flare gun, and I\'ll help you spot \'em.' WHERE `word_id` = 181840; -- locales_quest - details : entry=26648
UPDATE `trans_words` SET `content_loc7`='Hey, nice work! Keep this up and the other rogues might stop spitting on you.' WHERE `word_id` = 141615; -- locales_quest - offerrewardtext : entry=6701
UPDATE `trans_words` SET `content_loc7`='Hey, nice work!$B$BIf you ever want to come back and kill some more bugs for absolutely no additional reward, please, feel free!' WHERE `word_id` = 189024; -- locales_quest - offerrewardtext : entry=28703
UPDATE `trans_words` SET `content_loc7`='Hey, nice! I\'ll just take those... carefully... Don\'t go tellin\' the workers I didn\'t have the guts to go down there myself, you hear? Here\'s your pay... and a little somethin\' extra.' WHERE `word_id` = 187877; -- locales_quest - offerrewardtext : entry=28340
UPDATE `trans_words` SET `content_loc7`='Hey, now isn\'t that just the thing! You\'ve got our supplies back for us. That\'s great. I\'ll be able to get back to work just as soon as I can find someone to haul these sacks for me.' WHERE `word_id` = 133656; -- locales_quest - offerrewardtext : entry=834
UPDATE `trans_words` SET `content_loc7`='Hey, thanks, kid. Give it over, let\'s take a look. Oh, that ain\'t good.' WHERE `word_id` = 275231; -- locales_quest - offerrewardtext : entry=24536
UPDATE `trans_words` SET `content_loc7`='Hey, thanks, kid. Give it over, let\'s take a look.$B$B<He takes the device from you and fiddles with it.>$B$BOh, that ain\'t good.' WHERE `word_id` = 336293; -- locales_quest - offerrewardtext : entry=24655
UPDATE `trans_words` SET `content_loc7`='Hey, that wasn\'t too bad... are you sure you\'re not a dwarf?$B$BSo there\'s plenty more racing to be had and it\'s not just from me. All over the Brewfest grounds you\'ll find people in need of a decent ram racer. So go and make yourself useful.$B$BOh and don\'t forget, these rams were legally obtained. I just want to make sure we\'re clear.' WHERE `word_id` = 154325; -- locales_quest - offerrewardtext : entry=11409
UPDATE `trans_words` SET `content_loc7`='Hey, watch where you\'re pointing that thing! You\'ve got it set to \'Kill\'!!!$B$BIt looks like you\'ve recharged the battery, and then some. This\'ll help immensely to keep these guys going.' WHERE `word_id` = 150006; -- locales_quest - offerrewardtext : entry=10190
UPDATE `trans_words` SET `content_loc7`='Hey, while you were out, the Baron stopped by! He kicked me until money came out!$B$BHe always does that though. But this time he asked me to tell you something! He wants you to go south and help out our herbalist, Baba Bogbrew.$B$BShe\'s all the way across the water! But just talk to my girl Daisy outside and she\'ll send you there the Crazy Larry way!' WHERE `word_id` = 185577; -- locales_quest - details : entry=27740
UPDATE `trans_words` SET `content_loc7`='Hey, you have been saving! I\'m so proud of you! Um, boss... this isn\'t nearly enough.' WHERE `word_id` = 173331; -- locales_quest - offerrewardtext : entry=14122
UPDATE `trans_words` SET `content_loc7`='Hey, you look like a discriminating adventurer. Are you looking for something different?  Something exotic?  Something... profitable?$B$BWell shake the sand out of your boots, because I\'ve got a proposition for you. Williden Marshal is looking for competent sellswords such as yourself. He\'s set up camp at Marshal\'s Stand, just southeast of the volcano in the center of lush Un\'Goro Crater.$B$BThen again, paradise isn\'t for everyone, $R. It\'s up to you. Your tropical oasis awaits.' WHERE `word_id` = 175622; -- locales_quest - details : entry=24911
UPDATE `trans_words` SET `content_loc7`='Hey, you made it back alive!  Can\'t say you were the first one to try this task, but you are definitely the first one to make it back alive.' WHERE `word_id` = 186420; -- locales_quest - offerrewardtext : entry=27967
UPDATE `trans_words` SET `content_loc7`='Hey, you there!  Ye\'re a stout-looking $C. Lend us a hand?$B$BIt looks like today\'s big earthquake shook a bunch o\' those barbarous troggs out of the ground, and they\'re sure steamed about something. My men are doing what they can to hold them off, but we could use a hand.$B$BDo yer part - head just south of here and help dig me mountaineers outta trouble. We\'ve got to hold the line!' WHERE `word_id` = 174681; -- locales_quest - details : entry=24469
UPDATE `trans_words` SET `content_loc7`='Hey, you want to try my new diemetradon dogs?  No?  Raptor risotto?  Pterrordax ptacos?$B$BFine. Oh, I just remembered!  I have a friend nearby that might be able to use your assistance. His name is Spark Nilminer, and he\'s Marshal Expeditions\' chief archaeology officer.$B$BHe\'s been sent out to Golakka Hot Springs, to the west. You\'ll likely find him on the springs\' western shore.' WHERE `word_id` = 175290; -- locales_quest - details : entry=24698
UPDATE `trans_words` SET `content_loc7`='Hey, you\'re one big strong heap of $C. Can you handle the crucible? We got bookies are standing by!' WHERE `word_id` = 186668; -- locales_quest - offerrewardtext : entry=28038
UPDATE `trans_words` SET `content_loc7`='Hey, you\'re tougher than you look. These terrortooth hides reflect arrows and turn axe-blades - they don\'t go down easy, but their hides are worth their weight in silver in these light-forsaken Barrens. Nice work.' WHERE `word_id` = 175958; -- locales_quest - offerrewardtext : entry=25000
UPDATE `trans_words` SET `content_loc7`='Hey. man. that\'s great. We hear you\'ve been doing good things. That\'s cool. We\'ve got a feeling that you\'re going to make things right for us here in Ogri\'la, and keep us safe, and everything nice and mellow.$B$BHere, take this. It\'s nothing much, just a care package that we whipped up as a thanks for your effort.$B$BFeel free to look around at our goods. We have a lot of really choice stuff that you\'re gonna want to get.' WHERE `word_id` = 153635; -- locales_quest - offerrewardtext : entry=11091
UPDATE `trans_words` SET `content_loc7`='Hey. You got some time on your hands? I could use someone like you.' WHERE `word_id` = 275282; -- locales_quest - offerrewardtext : entry=24804
UPDATE `trans_words` SET `content_loc7`='Heya mon!  Bom\'bay be workin\' on some new mojo. You wanna try a piece of it?  Well, before ya do, Bom\'bay\'s gonna need ya to pick up some jujus.$B$BFirst, Bom\'bay needs ya to get some o\' the goop from the crabs down by the water. Let me see your hands!$B$B<Bom\'bay examines your hands closely.>$B$BBom\'bay gonna need 5 handfuls. Go on now!' WHERE `word_id` = 176586; -- locales_quest - details : entry=25170
UPDATE `trans_words` SET `content_loc7`='Heya, $N, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you\'ve been doing up here.$B$BAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I\'m certain they could use your help.' WHERE `word_id` = 184476; -- locales_quest - details : entry=27446
UPDATE `trans_words` SET `content_loc7`='Heya, $N, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you\'ve been doing up here.$B$BAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I\'m certain they could use your help.$B$BBesides, that Megs is a hottie!' WHERE `word_id` = 184479; -- locales_quest - details : entry=27447
UPDATE `trans_words` SET `content_loc7`='Heya, $N, there are strange cave paintings and other artifacts all over the cavern.$B$BDo you think you could use your belt-mounted KTC Snapflash camera to capture images at the designated spots? Also, snap a pic of the altar in the back of the cavern.$B$BI\'m sure that Sassy will want the intel.' WHERE `word_id` = 173146; -- locales_quest - details : entry=14031
UPDATE `trans_words` SET `content_loc7`='Heya, boss, Hobart Grapplehammer\'s wants to speak with you. He says it\'s a matter of some urgency.' WHERE `word_id` = 183605; -- locales_quest - details : entry=27139
UPDATE `trans_words` SET `content_loc7`='Heya, kid, I\'ll be right with ya. Just gotta shut this gnome twerp up first.' WHERE `word_id` = 177604; -- locales_quest - offerrewardtext : entry=25489
UPDATE `trans_words` SET `content_loc7`='Heya, pal, mind if I take a look at that list? What\'s Pozzik thinking? He knows that I don\'t have even half of that stuff!' WHERE `word_id` = 177663; -- locales_quest - offerrewardtext : entry=25505
UPDATE `trans_words` SET `content_loc7`='Hi friend! I don\'t think I know you... I\'m Donnelly Dunwald. What\'s your name? I don\'t think I know you... Do I know you?' WHERE `word_id` = 185226; -- locales_quest - offerrewardtext : entry=27643
UPDATE `trans_words` SET `content_loc7`='Hi there! The fun\'s already started!' WHERE `word_id` = 176420; -- locales_quest - offerrewardtext : entry=25121
UPDATE `trans_words` SET `content_loc7`='Hi there, $N. Yes, what Krakle told you is true...' WHERE `word_id` = 134275; -- locales_quest - offerrewardtext : entry=980
UPDATE `trans_words` SET `content_loc7`='Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn\'t mind company.' WHERE `word_id` = 134271; -- locales_quest - offerrewardtext : entry=979
UPDATE `trans_words` SET `content_loc7`='Hi! Really glad see you again!$B$BI knew we friends. I knew it! You good friend. Not just for us, but for all Oracles.$B$BI saw you bonk that puppy-man good! Undead thing said he your friend before? I not know that. You done with puppy-men though, yeah? Just Oracle friend now?$B$BI know you choose right! Thank you for saving us! Thank you, thank you!' WHERE `word_id` = 160821; -- locales_quest - offerrewardtext : entry=12689
UPDATE `trans_words` SET `content_loc7`='Hi, babe. Are you ready for the party?$B$BNo?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party.$B$BDon\'t look at me like that... you want to look your best? Don\'t you want to look good for me? I am your girlfriend after all!$B$BMake sure you swing by the bank first and pull out plenty of macaroons. Don\'t buy any of that cheap stuff!' WHERE `word_id` = 182071; -- locales_quest - details : entry=26712
UPDATE `trans_words` SET `content_loc7`='Hi, I\'m the town merchant!  And Bronwyn\'s my dad!$B$BSorry, I shouldn\'t get too excited. Father says it\'s not professional.$B$BAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?$B$BYou\'ll find a few panthers nearby, but if you want to see the big tigers, you\'ll have to go northwest from here... north of that big troll arena.' WHERE `word_id` = 182424; -- locales_quest - details : entry=26818
UPDATE `trans_words` SET `content_loc7`='Hiccup! Ho Ho!' WHERE `word_id` = 130326; -- locales_quest - offerrewardtext : entry=48
UPDATE `trans_words` SET `content_loc7`='Hiccup!$B$BI\'m a-lookin\' right at you but you keep bobbing up and down. Makin\' me dizzy. Hoho!$B$BHiccup!$B$BWhoa! Did ya feel that? Ground is a-shakin\', my friend. I need a drink.$B$BHiccup!' WHERE `word_id` = 135659; -- locales_quest - offerrewardtext : entry=1451
UPDATE `trans_words` SET `content_loc7`='Hidden caves on the backside of the island. How very interesting.$B$BWell, at least now I know where all of my missing spies are.' WHERE `word_id` = 161480; -- locales_quest - offerrewardtext : entry=12847
UPDATE `trans_words` SET `content_loc7`='Hidden Data gathered' WHERE `word_id` = 161548; -- locales_quest - ObjectiveText1 : entry=12860
UPDATE `trans_words` SET `content_loc7`='Hidden explosives detonated' WHERE `word_id` = 184690; -- locales_quest - ObjectiveText1 : entry=27494
UPDATE `trans_words` SET `content_loc7`='Hide behind the Neferset Frond and Uncover the Neferset Secret.' WHERE `word_id` = 186239; -- locales_quest - objectives : entry=27922
UPDATE `trans_words` SET `content_loc7`='Hideaway Survivors Rescued' WHERE `word_id` = 190162; -- locales_quest - ObjectiveText1 : entry=29237
UPDATE `trans_words` SET `content_loc7`='Hieroglyphs depicting a chained Tol\'vir mark the southeastern corner of the map.$B$BPerhaps Tahet was brought there when he was imprisoned.' WHERE `word_id` = 185471; -- locales_quest - details : entry=27707
UPDATE `trans_words` SET `content_loc7`='High Abbot spoken with' WHERE `word_id` = 159317; -- locales_quest - ObjectiveText2 : entry=12274
UPDATE `trans_words` SET `content_loc7`='High Chief Stillpine Warned' WHERE `word_id` = 147858; -- locales_quest - ObjectiveText1 : entry=9663
UPDATE `trans_words` SET `content_loc7`='High Chieftain Winterfall\'s absence has done little to quell the rage of the Winterfall. In his absence, their greatest warrior has rose to a position of terrible power.$B$BGrolnar the Berserk lurks in the cave at the top of Winterfall Village, gorged on enough corrupt firewater to kill ten lesser furbolgs.$B$BHe has become a bloated and horrible beast! Our warriors have been unable to face him... do you have the strength to defeat him, $C?' WHERE `word_id` = 188786; -- locales_quest - details : entry=28614
UPDATE `trans_words` SET `content_loc7`='High Commander Kamses has a special mission for me?$B$BWait... don\'t tell me. It\'s hyenas again, right?$B$BVery well, I shall do my best.$B$BMeet with me at the Sunwatcher\'s Ridge.$B$BI won\'t disappoint you.' WHERE `word_id` = 187344; -- locales_quest - details : entry=28210
UPDATE `trans_words` SET `content_loc7`='High Priest Amet\'s vote is the only one that is completely outside of our control.$B$BHe will vote as his divinations tell him and nothing we do will dissuade him.$B$BI figure that gives us even odds either way.$B$BThe only problem we face is that his clairvoyance has failed him ever since the barriers around Uldum fell.$B$BHe will not cast a vote unless he regains power over his divinations.$B$BTake the stairs at either side of the Vir\'naal Dam and Speak to him to see what you can do to help.' WHERE `word_id` = 185179; -- locales_quest - details : entry=27630
UPDATE `trans_words` SET `content_loc7`='High Priest Mu\'funu hexed at death' WHERE `word_id` = 160743; -- locales_quest - ObjectiveText1 : entry=12674
UPDATE `trans_words` SET `content_loc7`='High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him by the Refugee Caravan.' WHERE `word_id` = 152561; -- locales_quest - objectives : entry=10840
UPDATE `trans_words` SET `content_loc7`='High Priestess Kilnara be behind dis abomination. Dis ain\'t looking good. We should see to da dwarf and then make our way to see what other trouble be going on.' WHERE `word_id` = 189863; -- locales_quest - offerrewardtext : entry=29120
UPDATE `trans_words` SET `content_loc7`='High Priestess Lorthuna defeated' WHERE `word_id` = 182484; -- locales_quest - ObjectiveText2 : entry=26832
UPDATE `trans_words` SET `content_loc7`='High Priestess Siralen statue' WHERE `word_id` = 177925; -- locales_quest - ObjectiveText4 : entry=25581
UPDATE `trans_words` SET `content_loc7`='High Priestess Tua-Tua hexed at death' WHERE `word_id` = 160744; -- locales_quest - ObjectiveText2 : entry=12674
UPDATE `trans_words` SET `content_loc7`='High up in the cliffs above me there is a large crystal pylon. Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.$B$BMaybe you can make more of it than I can. I personally don\'t care what it does, so you needn\'t report back to me, but perhaps one of the scholars in Marshal\'s Stand might be interested in what you discover.' WHERE `word_id` = 175372; -- locales_quest - details : entry=24721
UPDATE `trans_words` SET `content_loc7`='Highbank boat bomb placed' WHERE `word_id` = 188695; -- locales_quest - ObjectiveText1 : entry=28592
UPDATE `trans_words` SET `content_loc7`='Highbank Defenders slain' WHERE `word_id` = 188707; -- locales_quest - ObjectiveText1 : entry=28594
UPDATE `trans_words` SET `content_loc7`='Highbank keep bomb placed' WHERE `word_id` = 188696; -- locales_quest - ObjectiveText2 : entry=28592
UPDATE `trans_words` SET `content_loc7`='Highborne Spirit Bound' WHERE `word_id` = 178683; -- locales_quest - ObjectiveText1 : entry=25766
UPDATE `trans_words` SET `content_loc7`='Highborne spirits released' WHERE `word_id` = 188419; -- locales_quest - ObjectiveText1 : entry=28513
UPDATE `trans_words` SET `content_loc7`='Higher ground secured' WHERE `word_id` = 188309; -- locales_quest - ObjectiveText1 : entry=28486
UPDATE `trans_words` SET `content_loc7`='Highland Mustangs Frightened' WHERE `word_id` = 159594; -- locales_quest - ObjectiveText1 : entry=12415
UPDATE `trans_words` SET `content_loc7`='Highland Mustangs Returned' WHERE `word_id` = 159589; -- locales_quest - ObjectiveText1 : entry=12414
UPDATE `trans_words` SET `content_loc7`='Highland Raptors slain' WHERE `word_id` = 179025; -- locales_quest - ObjectiveText1 : entry=25864
UPDATE `trans_words` SET `content_loc7`='Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion.' WHERE `word_id` = 191458; -- locales_quest - objectives : entry=29851
UPDATE `trans_words` SET `content_loc7`='Hilda\'s sending us weapons?  That\'s excellent news, $N. I was about ready to tell the lads to pack things up.' WHERE `word_id` = 157987; -- locales_quest - offerrewardtext : entry=11963
UPDATE `trans_words` SET `content_loc7`='Hill Captured' WHERE `word_id` = 176133; -- locales_quest - ObjectiveText1 : entry=25045
UPDATE `trans_words` SET `content_loc7`='Hill Defended' WHERE `word_id` = 176134; -- locales_quest - ObjectiveText2 : entry=25045
UPDATE `trans_words` SET `content_loc7`='Hill Fawn "saved"' WHERE `word_id` = 188348; -- locales_quest - ObjectiveText1 : entry=28495
UPDATE `trans_words` SET `content_loc7`='Hillsbrad Human Captured' WHERE `word_id` = 187039; -- locales_quest - ObjectiveText1 : entry=28138
UPDATE `trans_words` SET `content_loc7`='Hillsbrad Worgen slain' WHERE `word_id` = 183884; -- locales_quest - ObjectiveText1 : entry=27231
UPDATE `trans_words` SET `content_loc7`='Hippogryph to New Thalanaar' WHERE `word_id` = 177587; -- locales_quest - ObjectiveText1 : entry=25479
UPDATE `trans_words` SET `content_loc7`='Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They\'re wary of other races, but they\'re intelligent enough to recognize a friend of a friend.$B$BI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.' WHERE `word_id` = 177378; -- locales_quest - details : entry=25409
UPDATE `trans_words` SET `content_loc7`='Hippogryphs Rallied' WHERE `word_id` = 177381; -- locales_quest - ObjectiveText1 : entry=25409
UPDATE `trans_words` SET `content_loc7`='His clothes and bloodstains? If it\'s not tricks, it\'s something worse...' WHERE `word_id` = 182114; -- locales_quest - offerrewardtext : entry=26723
UPDATE `trans_words` SET `content_loc7`='His death will not have been in vain, friend. The information that Slinkin died for will be instrumental in defeating the Lich King. I promise you that we will make this right.' WHERE `word_id` = 159329; -- locales_quest - offerrewardtext : entry=12277
UPDATE `trans_words` SET `content_loc7`='His own key? That\'s incredible!$B$BI do not sense any disturbances in our timeline, so I suppose it was meant to occur all along. There\'s no turning back now, $N. The key is yours and only yours.' WHERE `word_id` = 148601; -- locales_quest - offerrewardtext : entry=9837
UPDATE `trans_words` SET `content_loc7`='Hit Smilin\' Timmy Sticks with a cannonball' WHERE `word_id` = 181838; -- locales_quest - ObjectiveText1 : entry=26647
UPDATE `trans_words` SET `content_loc7`='Hive\'Ashi infiltrated' WHERE `word_id` = 189582; -- locales_quest - ObjectiveText1 : entry=28899
UPDATE `trans_words` SET `content_loc7`='Hive\'Ashi Prisoner rescued' WHERE `word_id` = 189591; -- locales_quest - ObjectiveText1 : entry=28901
UPDATE `trans_words` SET `content_loc7`='Hiya! Lend a hand, would ya, bub?' WHERE `word_id` = 181032; -- locales_quest - offerrewardtext : entry=26409
UPDATE `trans_words` SET `content_loc7`='Hm, I haven\'t the eye to examine these bracers to see if any of them will be of any use, but I\'m sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.$B$BAfter all, I can\'t very well leave Booty Bay just to chat with those tiresome old mages.$B$BNot that I\'m worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it.' WHERE `word_id` = 132725; -- locales_quest - offerrewardtext : entry=601
UPDATE `trans_words` SET `content_loc7`='Hm, I\'m no expert with the construction of arms and armor. Their use, yes, but not their making.$B$BThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.' WHERE `word_id` = 135249; -- locales_quest - offerrewardtext : entry=1253
UPDATE `trans_words` SET `content_loc7`='Hm, let\'s try this...$B$BI can\'t believe it! This stuff is... terrible! That\'s great!$B$BWell I guess Stoley can keep the money he owes me. He\'s true to his word about Steamwheedle bilge rum. That stuff is as thick as gravel and burns like lava!' WHERE `word_id` = 137358; -- locales_quest - offerrewardtext : entry=2874
UPDATE `trans_words` SET `content_loc7`='Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can\'t very well stop you, can I?$B$BAt least let me provide you with some advice and directions.' WHERE `word_id` = 131329; -- locales_quest - offerrewardtext : entry=282
UPDATE `trans_words` SET `content_loc7`='Hm, while I am glad to hear that Tazan is no longer with us, a locked satchel does us no good. We need the information kept within.$B$BThis should prove a worthy second challenge for one who wishes to join the Shattered Hand.' WHERE `word_id` = 136563; -- locales_quest - offerrewardtext : entry=1963
UPDATE `trans_words` SET `content_loc7`='Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic.' WHERE `word_id` = 135115; -- locales_quest - offerrewardtext : entry=1196
UPDATE `trans_words` SET `content_loc7`='Hm, you took this from the corpse of one of the invading abominations?$B$BWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they wanted to create one inside Stormwind. It is good that they were unseccessful.' WHERE `word_id` = 145324; -- locales_quest - offerrewardtext : entry=9292
UPDATE `trans_words` SET `content_loc7`='Hm. No doubt you made your way here at first mention of my summons, yes? Of course. I would expect no less from a prospective Deathstalker.' WHERE `word_id` = 136434; -- locales_quest - offerrewardtext : entry=1885
UPDATE `trans_words` SET `content_loc7`='Hm... I can\'t read orcish very well, but this looks like a report... written by an orc spy!' WHERE `word_id` = 135171; -- locales_quest - offerrewardtext : entry=1219
UPDATE `trans_words` SET `content_loc7`='Hm... I have heard of this "Collector" but I don\'t know whom he\'s working for. Thank you for the schedule. It will help us solve this mystery.' WHERE `word_id` = 130650; -- locales_quest - offerrewardtext : entry=123
UPDATE `trans_words` SET `content_loc7`='Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it\'s certainly not my work.' WHERE `word_id` = 135344; -- locales_quest - offerrewardtext : entry=1319
UPDATE `trans_words` SET `content_loc7`='Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all three cities, who knows what we could accomplish?' WHERE `word_id` = 145368; -- locales_quest - offerrewardtext : entry=9326
UPDATE `trans_words` SET `content_loc7`='Hm... your report comes at a bad time. The Burning Blade is no longer seen here in Sen\'jin, but we will be vigilant in our efforts to prevent their return to the area. The orcs are friends of the Darkspear Trolls. Honorable friends. We want to help the orcs, but... we need help too.' WHERE `word_id` = 176459; -- locales_quest - offerrewardtext : entry=25133
UPDATE `trans_words` SET `content_loc7`='Hm... your report comes at a bad time. The Burning Blade is not seen here in Sen\'jin, but their evil has taken seed off the coast, on the Echo Isles.$B$BThe orcs are friends of the Darkspear Trolls. Honorable friends. We want to help the orcs, but... we need help too.' WHERE `word_id` = 133550; -- locales_quest - offerrewardtext : entry=805
UPDATE `trans_words` SET `content_loc7`='Hm... Zarm. You are still new to your path, but I sense the possibility for greatness in you.$B$BYou were born with gifts, $N. See that they do not go to waste.' WHERE `word_id` = 135845; -- locales_quest - offerrewardtext : entry=1507
UPDATE `trans_words` SET `content_loc7`='Hm? What unit are you with, $C? No matter, we need all hands. My fleet is in tatters and they\'ve broken into the hold. You armed? That\'s good enough for me.' WHERE `word_id` = 175638; -- locales_quest - offerrewardtext : entry=24921
UPDATE `trans_words` SET `content_loc7`='Hmm, a trap fashioned from the essence of dragon flame? I wonder how Sablemane comes by such rarified substances?$B$BIt does not matter. What does matter is that we are going to use it to slay a son of Gruul!' WHERE `word_id` = 152396; -- locales_quest - offerrewardtext : entry=10785
UPDATE `trans_words` SET `content_loc7`='Hmm, mostly usable. This is good stuff. I\'ve already got buyers lined up, of course. Here\'s your advance for the rest of the work you\'re gonna do for me and the Bilgewater Cartel...partner.' WHERE `word_id` = 175603; -- locales_quest - offerrewardtext : entry=24906
UPDATE `trans_words` SET `content_loc7`='Hmm, some dark magic enchants this soulstone. Let\'s see what\'s trapped inside, shall we?' WHERE `word_id` = 134231; -- locales_quest - offerrewardtext : entry=970
UPDATE `trans_words` SET `content_loc7`='Hmm, still a bit frazzled, are they? Well, you know what they say. Time heals all wounds. Except for those of the ambassador, of course...' WHERE `word_id` = 186565; -- locales_quest - offerrewardtext : entry=28002
UPDATE `trans_words` SET `content_loc7`='Hmm, these runes are indeed a language, $N, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon\'s signature: Lord Azrethoc.' WHERE `word_id` = 135763; -- locales_quest - offerrewardtext : entry=1480
UPDATE `trans_words` SET `content_loc7`='Hmm, this is from Einar, right? Hasn\'t delivered his skins to me in person for almost a week now. No doubt it\'s some differences with the wife!$B$BMaybe I\'ll have my wife go speak with Sida sometime...' WHERE `word_id` = 132146; -- locales_quest - offerrewardtext : entry=469
UPDATE `trans_words` SET `content_loc7`='Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.$B$BAs I\'m told, you deserve a reward for your part in these matters. Keep this up, $N; the Deathstalkers always have use of a good man.' WHERE `word_id` = 164920; -- locales_quest - offerrewardtext : entry=14418
UPDATE `trans_words` SET `content_loc7`='Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.$B$BFrom what I understand, you also deserve commendation for your performance. I hope that this will become routine for you, $N, my Deathstalkers always have use of a good man.' WHERE `word_id` = 136567; -- locales_quest - offerrewardtext : entry=1978
UPDATE `trans_words` SET `content_loc7`='Hmm, this news is troubling. Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.$B$BIf things don\'t improve, there will be fighting in Goldshire by the week\'s end!' WHERE `word_id` = 130304; -- locales_quest - offerrewardtext : entry=39
UPDATE `trans_words` SET `content_loc7`='Hmm, well, it\'s a start. It\'ll take a few weeks or months to fully clean out the infestation. After that, we\'ll have to get down there with some torches to burn away the webbing.$B$BYou\'ve done your duty well, $N, I\'m sure I can find something else for you to do.' WHERE `word_id` = 131760; -- locales_quest - offerrewardtext : entry=380
UPDATE `trans_words` SET `content_loc7`='Hmm, where the heck is the ignition? It\'ll be a wonder if it flies without doing something weird, like turning into a chicken or shrinking down to the size of an ant. Hey look, someone left their loose change in the ashtray! What else is in there?' WHERE `word_id` = 173633; -- locales_quest - offerrewardtext : entry=14241
UPDATE `trans_words` SET `content_loc7`='Hmm, yes, perhaps I could be of some assistance. When I was in Northrend I helped the people of Valgarde uncover some of the mysteries of the vrykul by delving into the spirit world. Perhaps the same could be done here.' WHERE `word_id` = 180680; -- locales_quest - offerrewardtext : entry=26319
UPDATE `trans_words` SET `content_loc7`='Hmm. From what you\'ve told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane. The Argent Dawn appreciates your service.' WHERE `word_id` = 145294; -- locales_quest - offerrewardtext : entry=12816
UPDATE `trans_words` SET `content_loc7`='Hmm. Maelik? No, the name doesn\'t sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think.' WHERE `word_id` = 131811; -- locales_quest - offerrewardtext : entry=392
UPDATE `trans_words` SET `content_loc7`='Hmm... <Jorgen looks up at you through squinted eyes.>$B$BAll right. I\'ll help ya, but not because I want to, but because I\'m obligated.$B$BAnd let\'s get one thing straight: you\'re knowin\' far more than you should to begin with. Let\'s keep this our little secret, and don\'t go blabbin\' at any taverns about anything you find out. Understand?' WHERE `word_id` = 135205; -- locales_quest - offerrewardtext : entry=1241
UPDATE `trans_words` SET `content_loc7`='Hmm... Don\'t suppose you\'d be interested in becoming my apprentice, would you?$B$BHah! No, I\'m just kidding. You\'re much too old, for one thing. Besides - from the looks of you, it would seem that you have other ambitions in life. Nonetheless, these are some fine skins you\'ve procured, and I\'ll be able to put them to good use.' WHERE `word_id` = 132156; -- locales_quest - offerrewardtext : entry=471
UPDATE `trans_words` SET `content_loc7`='Hmm... I remember hearing our scouts speak of the ruins of a draenei settlement in the forest\'s northern reaches. I don\'t know much about the ruins, personally, but you\'re welcome to talk to some of the scouts.' WHERE `word_id` = 148400; -- locales_quest - offerrewardtext : entry=9793
UPDATE `trans_words` SET `content_loc7`='Hmm... interesting. From what you\'re saying, it sounds like a fire elemental might have snuck in from Searing Gorge. Or, the earthquake opened up a crack to the elemental plane... Either way, this is bad news. You should probably report this information to Grelin.' WHERE `word_id` = 174766; -- locales_quest - offerrewardtext : entry=24489
UPDATE `trans_words` SET `content_loc7`='Hmm... Let\'s see what you\'ve got...$B$B<He begins to rifle through the documents you recovered.>$B$BSome news of their exploits against us... Worthless. Scouting reports... New orders, "Continue to build up a camp near the ruined city..." Nothing we didn\'t know already... Ah, what\'s this? A map of the dispositions of some of their field commanders and agents! We can use this.' WHERE `word_id` = 131769; -- locales_quest - offerrewardtext : entry=382
UPDATE `trans_words` SET `content_loc7`='Hmm... not bad. You\'re quicker than many of my men. Stick around, $N... I may have use of you yet.' WHERE `word_id` = 178441; -- locales_quest - offerrewardtext : entry=25710
UPDATE `trans_words` SET `content_loc7`='Hmm... now this is interesting.' WHERE `word_id` = 183922; -- locales_quest - offerrewardtext : entry=27260
UPDATE `trans_words` SET `content_loc7`='Hmm... so the bullets had quite a bit of spread?$B$BTo some people that may be a problem... me, though, I see it as a blessing in disguise!$B$BOur enemies will be running all over the place, so with a bit of a spread, the tank drivers won\'t need to lead the target!' WHERE `word_id` = 165411; -- locales_quest - offerrewardtext : entry=25295
UPDATE `trans_words` SET `content_loc7`='Hmm... so the left leg servo was activating the right leg?  But I saw the left leg moving...$B$BEh, details. I\'ll get to that later, but two out of three things worked: That isn\'t half bad!$B$BThanks for checking this out for me, $N.' WHERE `word_id` = 165396; -- locales_quest - offerrewardtext : entry=25289
UPDATE `trans_words` SET `content_loc7`='Hmm... Someone handled this book recently, someone who is driven by revenge. But the impressions left on it, at least the impressions from the original owner, are faint.$B$BI can tell, however, that the original owner of this book is not a native of Darkshire.' WHERE `word_id` = 131240; -- locales_quest - offerrewardtext : entry=262
UPDATE `trans_words` SET `content_loc7`='Hmm... the gems looked... sparklier from afar. Up close, they look kind of dingy. Ah well!  A little spit and polish should do the trick, and if not, I can use \'em to practice my disenchanting.' WHERE `word_id` = 186482; -- locales_quest - offerrewardtext : entry=27982
UPDATE `trans_words` SET `content_loc7`='Hmm... The soil seems to be depleted, so it can\'t be the cause of the problem, as I\'d thought. What\'s the common link here? Why is everything suddenly dying?' WHERE `word_id` = 148346; -- locales_quest - offerrewardtext : entry=9782
UPDATE `trans_words` SET `content_loc7`='Hmm... they blame us for destroying their home, ye say?  Well, that wasn\'t us, that was the horrible earthquake we had earlier today. Are they that dense that they can\'t see we nearly lost our camp too? Can\'t blame a trogg for fightin\' for his home, though.' WHERE `word_id` = 174688; -- locales_quest - offerrewardtext : entry=24470
UPDATE `trans_words` SET `content_loc7`='Hmm... they didn\'t survive the trip out of the water as well as I had hoped. Oh well!  Seafood salad for Frederick tonight!' WHERE `word_id` = 184494; -- locales_quest - offerrewardtext : entry=27450
UPDATE `trans_words` SET `content_loc7`='Hmm... They seem to be divided between images of a serpent spirit and a bird spirit. No self-respecting Darkspear troll engages in bird worship. Their spirits are weak, capricious, and best left to the Amani.$B$BBut the serpent, $N, the serpent wields considerable power and this is the spirit I shall study.' WHERE `word_id` = 148642; -- locales_quest - offerrewardtext : entry=9846
UPDATE `trans_words` SET `content_loc7`='Hmm... this is a rather small amount. but if we\'re careful. it should be sufficient. You see. the Scarlet Crusade believes itself dedicated to the Light. I suppose they still are, in a twisted sort of way, and that\'s exactly what I\'m hoping to capitalize on.$B$BTheir misguided zeal has even tainted the blessing spoken over this water, making it ideal for my purpose.' WHERE `word_id` = 148161; -- locales_quest - offerrewardtext : entry=9735
UPDATE `trans_words` SET `content_loc7`='Hmm... this is most intriguing. Yes, I should be able to make out what the original author wrote in the pages of this book.$B$BI should have everything I need for the process. This should only take a moment.' WHERE `word_id` = 147466; -- locales_quest - offerrewardtext : entry=9557
UPDATE `trans_words` SET `content_loc7`='Hmm... yes, that makes sense. Since the worgen have come streaming out of Gilneas, I knew it would only be a matter of time before they arrived here in Tirisfal.' WHERE `word_id` = 175928; -- locales_quest - offerrewardtext : entry=24992
UPDATE `trans_words` SET `content_loc7`='Hmm... yes, these seeds will do nicely. You have the gratitude of the Cenarion Circle, $N.' WHERE `word_id` = 175243; -- locales_quest - offerrewardtext : entry=24686
UPDATE `trans_words` SET `content_loc7`='Hmm... you don\'t look like a research assistant, which is just as well. The iron dwarves look to be preparing for war, and my research team hasn\'t returned. We could use some help around here.' WHERE `word_id` = 158648; -- locales_quest - offerrewardtext : entry=12128
UPDATE `trans_words` SET `content_loc7`='Hmm... you got a lot of fish, but none of these are the ones that ate my wolf. I think it was probably a bigger fish.' WHERE `word_id` = 179854; -- locales_quest - offerrewardtext : entry=26088
UPDATE `trans_words` SET `content_loc7`='Hmm...$B$BIt seems I was right. There is a pattern here.$B$BThe most aggressive and dangerous ghosts coincide with the most powerful and highest ranking Kirin Tor who resided in the village. The townspeople and tradesmen seem overlooked by comparison. What could this mean?' WHERE `word_id` = 150565; -- locales_quest - offerrewardtext : entry=10312
UPDATE `trans_words` SET `content_loc7`='Hmm...$B$BThis looks edible, if spiced properly. Just don\'t tell Screed where his breakfast came from, ok?' WHERE `word_id` = 146740; -- locales_quest - offerrewardtext : entry=9361
UPDATE `trans_words` SET `content_loc7`='Hmm?  Barnil\'s the name. And you are...?' WHERE `word_id` = 180769; -- locales_quest - offerrewardtext : entry=26340
UPDATE `trans_words` SET `content_loc7`='Hmmm, Narm sent you to me, did he?$B$BWell then, Narm could always be trusted, so that must mean you\'re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You\'ve tasted power, and now you\'re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.' WHERE `word_id` = 135901; -- locales_quest - offerrewardtext : entry=1523
UPDATE `trans_words` SET `content_loc7`='Hmmm, not bad, $N. But don\'t let it get to your head...you\'ll fight tougher than boars in your career.$B$BNonetheless, you\'ve proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you\'ll need some extra protection.' WHERE `word_id` = 133515; -- locales_quest - offerrewardtext : entry=25126
UPDATE `trans_words` SET `content_loc7`='Hmmm, now this is interesting. You\'ve more than proved your worth with this, Weir. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think.' WHERE `word_id` = 136390; -- locales_quest - offerrewardtext : entry=1858
UPDATE `trans_words` SET `content_loc7`='Hmmm, Searn sent you to me, did he?$B$BWell then, Searn could always be trusted, so that must mean you\'re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You\'ve tasted power, and now you\'re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.' WHERE `word_id` = 135899; -- locales_quest - offerrewardtext : entry=1522
UPDATE `trans_words` SET `content_loc7`='Hmmm, so my information was correct, as usual. Interesting. Well, I don\'t suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products. Hmmm...' WHERE `word_id` = 130992; -- locales_quest - offerrewardtext : entry=201
UPDATE `trans_words` SET `content_loc7`='Hmmm, Swart sent you to me, did he?$B$BWell then, Swart could always be trusted, so that must mean you\'re ready to take part of the next sapta--the sapta of fire.$B$BI see it in your eyes already, the burning, the desire. You\'ve tasted power, and now you\'re ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.' WHERE `word_id` = 137641; -- locales_quest - offerrewardtext : entry=2983
UPDATE `trans_words` SET `content_loc7`='Hmmm, yes? My investigation of the Twilight\'s Hammer. Of course. Your assistance will be valuable.' WHERE `word_id` = 183004; -- locales_quest - offerrewardtext : entry=26977
UPDATE `trans_words` SET `content_loc7`='Hmmm... just as I suspected.$B$BExposure to this level of raw energy greatly magnifies our innate addiction to magic.$B$BI\'m not surprised Kael gets away with what he does; all his subordinates are basically drunk on this.' WHERE `word_id` = 150075; -- locales_quest - offerrewardtext : entry=10204
UPDATE `trans_words` SET `content_loc7`='Hmmm... strangely enough I don\'t feel any better about my brother\'s death at the hands of those brutes.$B$BWell, you held your end of the bargain. Let\'s see what I can do for you.' WHERE `word_id` = 144637; -- locales_quest - offerrewardtext : entry=8949
UPDATE `trans_words` SET `content_loc7`='Hmmmmph... these will do for now. There seems to be some oddness to them.$B$BI tell ya - I\'ve handled body parts for years now and never have I had such a weird feeling in my stomach. Anyway, a deal is a deal. Here\'s your payment.' WHERE `word_id` = 156563; -- locales_quest - offerrewardtext : entry=11424
UPDATE `trans_words` SET `content_loc7`='Hmmmphh.... it seems they\'ll let anyone in these days.$B$BVery well. You doubtlessly became acquainted with Smolderos in the proving grounds.$B$BWell, I\'ve been entrusted with the care of one of his pups. Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.$B$BCollect meat from the basilisks around the area and feed them to him.' WHERE `word_id` = 177005; -- locales_quest - details : entry=25294
UPDATE `trans_words` SET `content_loc7`='Hmmph... it looks like your services are being requested elsewhere. Ag\'tor Bloodfist is looking for recruits to assist the Horde\'s ventures in Azshara, north of Orgrimmar.$B$BI\'m sure you still have work to do here in Durotar, and I understand that they\'ll shortly be asking for your help in the Barrens. I wouldn\'t be going anywhere yet if I were you, but if you\'re itching for some manifest destiny... Azshara awaits.' WHERE `word_id` = 178155; -- locales_quest - details : entry=25648
UPDATE `trans_words` SET `content_loc7`='Hmmphh.... the reports from the field are.... not encouraging!' WHERE `word_id` = 155446; -- locales_quest - offerrewardtext : entry=11170
UPDATE `trans_words` SET `content_loc7`='Hmph, it\'ll take more than a Dark Iron ambush to stop the deliveries!$B$BBut Saean... I would never have suspected him to be one of their sympathizers. We\'ve been working with him for almost a year now... maybe I missed the signs.$B$BWell, I\'ll consider that later.' WHERE `word_id` = 131288; -- locales_quest - offerrewardtext : entry=13639
UPDATE `trans_words` SET `content_loc7`='Hmph, you\'re my sponsor?  I\'m Salandria!  I\'ve been here ever since I was a little baby. My parents were taken by the war, so I have to live here at the orphanage.$B$BIt\'s not that bad, but I always wanted to go places -- I haven\'t ever stepped foot outside of the city. I\'ve already made a list of all the cool places that I want to go, and the awesome things that I want to do.$B$BI\'m ready to go when you are!' WHERE `word_id` = 273569; -- locales_quest - offerrewardtext : entry=10942
UPDATE `trans_words` SET `content_loc7`='Hmph. Good work, grunt.' WHERE `word_id` = 187492; -- locales_quest - offerrewardtext : entry=28245
UPDATE `trans_words` SET `content_loc7`='Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.$B$BIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.' WHERE `word_id` = 135300; -- locales_quest - offerrewardtext : entry=1273
UPDATE `trans_words` SET `content_loc7`='Hmph. Just looks like a big lump of unrefined crystal to me.$B$BAdmittedly, I can feel a sickly, evil aura emanating off of it, but that\'s not exactly in my line of work. I\'m just here to put an end to the mountain giant menace.' WHERE `word_id` = 149788; -- locales_quest - offerrewardtext : entry=10134
UPDATE `trans_words` SET `content_loc7`='Ho ho hello, adventurer!$B$BThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you. Here you go - have a wondrous Feast of Winter Veil this and every season in the future.' WHERE `word_id` = 141740; -- locales_quest - offerrewardtext : entry=6984
UPDATE `trans_words` SET `content_loc7`='Ho ho hello. I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... "Fresh from our farm to your plate, it\'s Smokywood Pastures wholesome goodness" - would like to wish you a fantastic Feast of Winter Veil.$B$BIf you\'ve been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil. Huzzah.' WHERE `word_id` = 141710; -- locales_quest - offerrewardtext : entry=6961
UPDATE `trans_words` SET `content_loc7`='Ho ho! Come for your free beer?' WHERE `word_id` = 154350; -- locales_quest - offerrewardtext : entry=11441
UPDATE `trans_words` SET `content_loc7`='Ho ho! The beach is ours! We just might keep a foothold on this miserable dustball of a continent after all.' WHERE `word_id` = 175706; -- locales_quest - offerrewardtext : entry=24939
UPDATE `trans_words` SET `content_loc7`='Ho! I knew you were a $C I could count on, $N. Use that portal anytime you need to get from Stormwind back to the Highlands. Now then, time to get to business. We need to locate and unite the lost Wildhammer clans scattered around the Highlands. Talking with Thordun here is a good start!' WHERE `word_id` = 184899; -- locales_quest - offerrewardtext : entry=27545
UPDATE `trans_words` SET `content_loc7`='Hobart thinks he\'s going to feed us on those tiny clucker eggs? Bah! We\'re going to get some real eggs!$B$BI\'ve already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you\'ll get to trade up to their larger eggs.$B$BGenius!' WHERE `word_id` = 175409; -- locales_quest - details : entry=24741
UPDATE `trans_words` SET `content_loc7`='Hodir\'s Helm Mounted' WHERE `word_id` = 162109; -- locales_quest - ObjectiveText1 : entry=12987
UPDATE `trans_words` SET `content_loc7`='Hold back the worgen atop the Gilneas City Prison for 2 minutes.' WHERE `word_id` = 173411; -- locales_quest - objectives : entry=14154
UPDATE `trans_words` SET `content_loc7`='Hold off the attackers and speak with Rilak.' WHERE `word_id` = 152746; -- locales_quest - objectives : entry=10879
UPDATE `trans_words` SET `content_loc7`='Hold on tight, $N. The journey back to the waking world can be a little rough on unprepared minds and bodies.' WHERE `word_id` = 172852; -- locales_quest - details : entry=13940
UPDATE `trans_words` SET `content_loc7`='Hold still a second, I\'m going to bring your main buzzsaw controls online.$B$BNight elven snipers from Talrendis have been hiding in the trees, taking potshots at my workers. I want you to take care of those snipers... by first taking care of those trees. Look for Azshara saplings east of the main gates. Your shredder will know what to do. Chop to it!' WHERE `word_id` = 173394; -- locales_quest - details : entry=14135
UPDATE `trans_words` SET `content_loc7`='Hold the bridge on Quel\'Dormir Terrace until Lady Sira\'kess\' allies arrive.$B$BThis task is part of a Naz\'jar Battlemaiden vision. If needed, use the Blade of the Naz\'jar Battlemaiden at a time focus to return to the vision.' WHERE `word_id` = 179399; -- locales_quest - objectives : entry=25951
UPDATE `trans_words` SET `content_loc7`='Hold the eastern end of Quel\'Dormir Terrace' WHERE `word_id` = 179401; -- locales_quest - ObjectiveText1 : entry=25951
UPDATE `trans_words` SET `content_loc7`='Hold there, stranger!' WHERE `word_id` = 179346; -- locales_quest - offerrewardtext : entry=25938
UPDATE `trans_words` SET `content_loc7`='Holdfast Cannons destroyed' WHERE `word_id` = 177945; -- locales_quest - ObjectiveText1 : entry=25585
UPDATE `trans_words` SET `content_loc7`='Holding the energized stave is almost impossible. Its power rumbles through your body.$B$BYou reach out to the cold surface of the Equinex Monolith...$B$BA small door opens, allowing you to reach in and take the artifact inside.$B$BBeams of light fill the area around the Equinex Monolith.' WHERE `word_id` = 137378; -- locales_quest - offerrewardtext : entry=2879
UPDATE `trans_words` SET `content_loc7`='Holey moley, you did it!$B$BAlright, now those pesky magnataur and their snobold flunkies should turn their attentions on the Horde.$B$BHow can I ever repay you, $N?' WHERE `word_id` = 157293; -- locales_quest - offerrewardtext : entry=11670
UPDATE `trans_words` SET `content_loc7`='Holland?  He\'s an amateur. You don\'t need a fancy two-story apothecarium to make plague... you need love. And maybe some good assistants. Let me show you how plague is REALLY made.' WHERE `word_id` = 175924; -- locales_quest - offerrewardtext : entry=24991
UPDATE `trans_words` SET `content_loc7`='Hollee. is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.$B$BHey, you\'re not Hollee! Don\'t suppose you\'ve seen my stone brush?$B$BNever mind that now! I promised the League I\'d send the mysterious fossil I found. Where did Hollee go?$B$BSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...$B$BAnd who are you... \'tis no matter, so long as you\'re here to help.$B$BLet me know when you\'re ready to start looking.' WHERE `word_id` = 133270; -- locales_quest - offerrewardtext : entry=729
UPDATE `trans_words` SET `content_loc7`='Holy... what the hell?! Look at this stuff!$B$BWe need to get this back to the keep a.s.a.p.!' WHERE `word_id` = 156369; -- locales_quest - offerrewardtext : entry=11327
UPDATE `trans_words` SET `content_loc7`='Holyfiresnub has returned! And in one piece! Defender of Silverpine! Redeemer of the Horde! Holyfiresnub, your bravery must be rewarded!' WHERE `word_id` = 183054; -- locales_quest - offerrewardtext : entry=26989
UPDATE `trans_words` SET `content_loc7`='Honestly? I wouldn\'t have thought it. You\'re amazing, $N. Taking on demons for a mage\'s experiments, and coming back in one piece to boot. Great job!$B$BI\'m personally gonna tell Roetten about you when I get back to Ironforge.' WHERE `word_id` = 135702; -- locales_quest - offerrewardtext : entry=1466
UPDATE `trans_words` SET `content_loc7`='Honey! Delicious honey! Well done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there.' WHERE `word_id` = 186507; -- locales_quest - offerrewardtext : entry=27989
