UPDATE `trans_words` SET `content_loc7`='Infiltrators\' encampment burnt' WHERE `word_id` = 177891; -- locales_quest - ObjectiveText1 : entry=25574
UPDATE `trans_words` SET `content_loc7`='Inform Aggra at the Horde Base Camp on the Lost Isles of all that has transpired.' WHERE `word_id` = 173876; -- locales_quest - objectives : entry=14303
