UPDATE `trans_words` SET `content_loc7`='Information beaten out of Apprentice Osterkilgr' WHERE `word_id` = 162305; -- locales_quest - ObjectiveText1 : entry=13042
UPDATE `trans_words` SET `content_loc7`='Information from Moonbrook Rally gathered' WHERE `word_id` = 180591; -- locales_quest - ObjectiveText1 : entry=26297
UPDATE `trans_words` SET `content_loc7`='Information gained for The Bone Witch' WHERE `word_id` = 162654; -- locales_quest - ObjectiveText1 : entry=13121
