UPDATE `trans_words` SET `content_loc7`='Information Recovered' WHERE `word_id` = 138422; -- locales_quest - ObjectiveText1 : entry=3701
UPDATE `trans_words` SET `content_loc7`='Information we\'ve received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands. According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.$B$BKill 3 of his zealots and 3 of his missionaries. And while you\'re there, see if you can dig up any other information about what they\'re up to.' WHERE `word_id` = 175895; -- locales_quest - details : entry=24981
UPDATE `trans_words` SET `content_loc7`='Infuriating! This entire fiasco!$B$BThe two of them were warned about how dangerous coming here would be. Now they\'re both missing... or worse.$B$BYou said you saw tracks heading to a fort nearby? That may be our best bet.$B$BFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde\'s beliefs, but they are evil and will slay you on sight if you\'re caught spying.' WHERE `word_id` = 135699; -- locales_quest - offerrewardtext : entry=1465
UPDATE `trans_words` SET `content_loc7`='Infused with Elementium, these weapons will cut through the Qiraji and their God with incredible ease.' WHERE `word_id` = 144344; -- locales_quest - offerrewardtext : entry=8789
UPDATE `trans_words` SET `content_loc7`='Injured 7th Legion Soldier Saved' WHERE `word_id` = 159757; -- locales_quest - ObjectiveText1 : entry=12457
UPDATE `trans_words` SET `content_loc7`='Injured Assault Volunteers rescued' WHERE `word_id` = 178626; -- locales_quest - ObjectiveText1 : entry=25753
UPDATE `trans_words` SET `content_loc7`='Injured Earthen patched up' WHERE `word_id` = 181633; -- locales_quest - ObjectiveText1 : entry=26591
UPDATE `trans_words` SET `content_loc7`='Injured Fawn Escorted Home' WHERE `word_id` = 177322; -- locales_quest - ObjectiveText1 : entry=25392
UPDATE `trans_words` SET `content_loc7`='Injured Razor Hill Grunt Rescued' WHERE `word_id` = 176626; -- locales_quest - ObjectiveText1 : entry=25179
UPDATE `trans_words` SET `content_loc7`='Injured Soldier Revived' WHERE `word_id` = 189296; -- locales_quest - ObjectiveText1 : entry=28806
