UPDATE `trans_words` SET `content_loc7`='Lady Dena Kennedy wants you to seek out Rilak the Redeemed in Shattrath and find out what secrets he will share of the Arakkoa.' WHERE `word_id` = 152673; -- locales_quest - objectives : entry=10863
