UPDATE `trans_words` SET `content_loc7`='Locate any refugees from Auberdine that are still alive.' WHERE `word_id` = 172050; -- locales_quest - objectives : entry=13518
UPDATE `trans_words` SET `content_loc7`='Locate Apex and obtain Apex\'s Crystal Focus from him. Return to the Violet Tower and use  Apex\'s Crystal Focus near Archmage Vargoth\'s Orb to discover who holds the key to breaking the tower\'s curse.' WHERE `word_id` = 150307; -- locales_quest - objectives : entry=10256
