UPDATE `trans_words` SET `content_loc7`='Partygoer entertained' WHERE `word_id` = 173300; -- locales_quest - ObjectiveText1 : entry=14113
UPDATE `trans_words` SET `content_loc7`='Pass through the portal atop Nordune Ridge and help Malfurion secure a foothold on the Molten Front.' WHERE `word_id` = 190420; -- locales_quest - objectives : entry=29201
UPDATE `trans_words` SET `content_loc7`='Pass through Zanzil\'s Portal' WHERE `word_id` = 181474; -- locales_quest - ObjectiveText1 : entry=26552
UPDATE `trans_words` SET `content_loc7`='Pass through Zanzil\'s Portal.$B$BIf you become lost or need to return to Zul\'Gurub, speak with Chabal at Hardwrench Hideaway.' WHERE `word_id` = 181480; -- locales_quest - objectives : entry=26554
