UPDATE `trans_words` SET `content_loc7`='Patches freed' WHERE `word_id` = 162817; -- locales_quest - ObjectiveText1 : entry=13152
UPDATE `trans_words` SET `content_loc7`='Patrolling the high road is grave business, but it must be done. These narrow mountain trails are, for the time being, one of our only lifelines into Stonetalon. They must be preserved.$B$BThank you.' WHERE `word_id` = 174822; -- locales_quest - offerrewardtext : entry=24504
UPDATE `trans_words` SET `content_loc7`='Paul\'s Test Questgiver wants you to kill zombies.' WHERE `word_id` = 174649; -- locales_quest - objectives : entry=24460
UPDATE `trans_words` SET `content_loc7`='Paul\'s Test Questgiver wants you to obtain 5 Trogg Items.' WHERE `word_id` = 174653; -- locales_quest - objectives : entry=24462
UPDATE `trans_words` SET `content_loc7`='Peace, friend. I wish we could have met under less troubling circumstances.' WHERE `word_id` = 181626; -- locales_quest - offerrewardtext : entry=26589
UPDATE `trans_words` SET `content_loc7`='Peachy. Back to work then. Thanks, snookums.' WHERE `word_id` = 173591; -- locales_quest - offerrewardtext : entry=14230
UPDATE `trans_words` SET `content_loc7`='Peak Grindstone\'s team broke down somewhere out there to the west.$B$BThink you can make yourself useful for a change and rush some parts out to them, $R?' WHERE `word_id` = 183570; -- locales_quest - details : entry=27126
UPDATE `trans_words` SET `content_loc7`='Pearl Miners rescued' WHERE `word_id` = 179211; -- locales_quest - ObjectiveText1 : entry=25907
UPDATE `trans_words` SET `content_loc7`='Pebble brought to crystal formation' WHERE `word_id` = 181142; -- locales_quest - ObjectiveText1 : entry=26440
UPDATE `trans_words` SET `content_loc7`='Pebble brought to safety' WHERE `word_id` = 182066; -- locales_quest - ObjectiveText1 : entry=26710
UPDATE `trans_words` SET `content_loc7`='Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths.$B$BHe\'s fortunate that his size makes him unworthy of the effort for those gyreworms, but it\'s only a matter of time before he stumbles too close to one and gets eaten. Whatever he\'s so intent on down there is certainly not worth it.$B$BHe seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.' WHERE `word_id` = 182063; -- locales_quest - details : entry=26710
UPDATE `trans_words` SET `content_loc7`='Peer into the Eye of Twilight for Garona.' WHERE `word_id` = 186368; -- locales_quest - objectives : entry=27955
