UPDATE `trans_words` SET `content_loc7`='Portals Banished' WHERE `word_id` = 140505; -- locales_quest - ObjectiveText1 : entry=14374
UPDATE `trans_words` SET `content_loc7`='Portanuus sent you? Good, we haven\'t any time to spare!' WHERE `word_id` = 154465; -- locales_quest - offerrewardtext : entry=11517
