UPDATE `trans_words` SET `content_loc7`='Sam\'s in one piece then? And his poor assistant Felice? Good to hear. I hope that one day he\'ll learn to respect the elements as more than just a tool.' WHERE `word_id` = 177507; -- locales_quest - offerrewardtext : entry=25456
UPDATE `trans_words` SET `content_loc7`='Samia Inkling has asked you to acquire 5 Wyrmcult Nets and return them to her at Evergrove in the Blade\'s Edge Mountains.' WHERE `word_id` = 152095; -- locales_quest - objectives : entry=10717
