UPDATE `trans_words` SET `content_loc7`='Samir wants you to collect 3 Rent Scrap Metal from Frenzied Orca in the Kelp Forest.$B$BYou can lure an orca using Pincer Entrails from Clacksnap Pincers.' WHERE `word_id` = 177289; -- locales_quest - objectives : entry=25384
