UPDATE `trans_words` SET `content_loc7`='Sen\'jin Frogs attuned' WHERE `word_id` = 165464; -- locales_quest - ObjectiveText2 : entry=25444
UPDATE `trans_words` SET `content_loc7`='Senani Thunderheart at Silverwind Retreat wants you to collect 15 Furbolg Ears from Foulweald Totemics and Foulweald Ursas.' WHERE `word_id` = 172934; -- locales_quest - objectives : entry=13967
UPDATE `trans_words` SET `content_loc7`='Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There\'s only so much room and so many teachers in Stormwind. With all the increased traffic, we\'re sure to attract attention sooner or later.' WHERE `word_id` = 136208; -- locales_quest - offerrewardtext : entry=1715
UPDATE `trans_words` SET `content_loc7`='Sentinel Elissa Starbreeze\'s spirit coaxed' WHERE `word_id` = 172132; -- locales_quest - ObjectiveText2 : entry=13547
UPDATE `trans_words` SET `content_loc7`='Sentinel Glynda Na\'Shea at Lor\'danel has requested that you join one of her sentinels on an aerial scouting mission. Speak to her when you are prepared to depart.' WHERE `word_id` = 172322; -- locales_quest - objectives : entry=13608
UPDATE `trans_words` SET `content_loc7`='Sentinel Lendra at Lor\'danel wants you to speak to Priestess Alinya at the Refugee Camp.' WHERE `word_id` = 172308; -- locales_quest - objectives : entry=13601
UPDATE `trans_words` SET `content_loc7`='Sentinel Moonwhisper at the tunnel between Zangarmarsh and Blade\'s Edge Mountains wants you to kill 6 Cavern Crawlers and report to Commander Skyshadow in Sylvanaar.' WHERE `word_id` = 152953; -- locales_quest - objectives : entry=10927
UPDATE `trans_words` SET `content_loc7`='Sentinel training 101: take out their leaders and your enemy\'s forces will soon fall apart. We\'re going to do just that, $C.$B$BIsha Gloomaxe is the closest of the Grimtotem chiefs. Let\'s see if we can\'t take her measure.' WHERE `word_id` = 184065; -- locales_quest - details : entry=27314
UPDATE `trans_words` SET `content_loc7`='Sentinel\'s Game Completed' WHERE `word_id` = 185483; -- locales_quest - ObjectiveText1 : entry=27709
UPDATE `trans_words` SET `content_loc7`='Sergeant Flinthammer? I\'m not familiar with the name, but, aye, there is a Flinthammer among the miners. He\'s one of the ones lucky enough to make it out of the mine, but most of my men are still trapped down there.' WHERE `word_id` = 179324; -- locales_quest - offerrewardtext : entry=25933
UPDATE `trans_words` SET `content_loc7`='Sergeant Gray has asked you to kill Commander Largo at Largo\'s Overlook. The overlook is just northeast of the base camp.' WHERE `word_id` = 186517; -- locales_quest - objectives : entry=27991
UPDATE `trans_words` SET `content_loc7`='Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.' WHERE `word_id` = 186444; -- locales_quest - objectives : entry=27973
