UPDATE `trans_words` SET `content_loc7`='Slaying the foul creatures that plague the river will not be enough, $N.$B$BA new generation of these monstrosities already threatens to spawn within our holy waters.$B$BSeek their foul eggs and destroy them.' WHERE `word_id` = 185962; -- locales_quest - details : entry=27836
