UPDATE `trans_words` SET `content_loc7`='Slow down, $C! You look as though you\'ve seen a ghost...' WHERE `word_id` = 178236; -- locales_quest - offerrewardtext : entry=25665
UPDATE `trans_words` SET `content_loc7`='Slow down, $N. I am but a lowly rogue. I have no idea what to do with such information.' WHERE `word_id` = 148813; -- locales_quest - offerrewardtext : entry=9890
UPDATE `trans_words` SET `content_loc7`='Slow down, $N. Why don\'t you start again... from the beginning?' WHERE `word_id` = 163778; -- locales_quest - offerrewardtext : entry=13401
UPDATE `trans_words` SET `content_loc7`='Slowly, but surely, we pick away at the Horde\'s numbers. They won\'t have a leg to stand on when this war really opens up.' WHERE `word_id` = 179086; -- locales_quest - offerrewardtext : entry=25879
UPDATE `trans_words` SET `content_loc7`='Smart boy! I can most definitely use these arcane remnants in my studies. Indeed, Dalaran was built upon a massive ley line. It\'s no wonder, then, that such things exist at the crater.' WHERE `word_id` = 184625; -- locales_quest - offerrewardtext : entry=27480
UPDATE `trans_words` SET `content_loc7`='Smart mining monkeys!$B$BThey\'re all over the inside of the cavern, mining... with picks! It\'s just not natural and I\'m sure it\'s because of the kaja\'mite!$B$BNone of my miners have come back out. I don\'t have many left! You can see my predicament, $N.$B$B<The foreman lowers his voice.>$B$BThese guys are nowhere near as good as my old group of jungle trolls. Ah, those were the days.$B$BMaybe you can escort my last miner here through the cavern and keep those monkeys off of him? We need that kaja\'mite!' WHERE `word_id` = 173135; -- locales_quest - details : entry=14021
UPDATE `trans_words` SET `content_loc7`='Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.' WHERE `word_id` = 185609; -- locales_quest - objectives : entry=27747
UPDATE `trans_words` SET `content_loc7`='Smash 30 Sand Pygmies with the Tahret Dynasty Mallet.' WHERE `word_id` = 187512; -- locales_quest - objectives : entry=28250
UPDATE `trans_words` SET `content_loc7`='Smashing! We\'ve cut off their supply line. Now all that we need to do is finish them off!' WHERE `word_id` = 148189; -- locales_quest - offerrewardtext : entry=9740
UPDATE `trans_words` SET `content_loc7`='Smear Pagle\'s Fish Paste, Extra Strength on yourself, then swim into Tidefury Cove.' WHERE `word_id` = 183847; -- locales_quest - objectives : entry=27220
UPDATE `trans_words` SET `content_loc7`='Smells like someone else was in this cell recently. Gross!' WHERE `word_id` = 183115; -- locales_quest - offerrewardtext : entry=27003
UPDATE `trans_words` SET `content_loc7`='Smiling Jim wants you to talk to Vern Futzwidget in Thousand Needles.' WHERE `word_id` = 176342; -- locales_quest - objectives : entry=25101
UPDATE `trans_words` SET `content_loc7`='Smite them all and let Hakkar sort them out...' WHERE `word_id` = 142755; -- locales_quest - offerrewardtext : entry=8052
