UPDATE `trans_words` SET `content_loc7`='Speak to Alamar Grimm and learn Immolate, then cast Immolate on a Training Dummy in New Tinkertown 5 times.' WHERE `word_id` = 180236; -- locales_quest - objectives : entry=26201
