UPDATE `trans_words` SET `content_loc7`='Speak to Anara to return to the world of the living, then meet with Kalecgos at the Northern Rocketway Terminus.' WHERE `word_id` = 174211; -- locales_quest - objectives : entry=14391
UPDATE `trans_words` SET `content_loc7`='Speak to Ander Germaine in Stormwind\'s Command Center.' WHERE `word_id` = 183858; -- locales_quest - objectives : entry=27225
