UPDATE `trans_words` SET `content_loc7`='Stand steady while I cast the final invocation of protection.$B$B<Vaelan\'s eyes turn to twin orbs of flame.>$B$BThe Seal of Ascension is complete...$B$BKnow this, I have imbued the artifact with some powerful protective wards. In your darkest hour, when all appears to be lost, the might of the red flight will be at your disposal.' WHERE `word_id` = 139361; -- locales_quest - offerrewardtext : entry=4743
UPDATE `trans_words` SET `content_loc7`='Stardust No. 2 Tested' WHERE `word_id` = 176542; -- locales_quest - ObjectiveText1 : entry=25157
UPDATE `trans_words` SET `content_loc7`='Start a bar fight!' WHERE `word_id` = 177705; -- locales_quest - objectives : entry=25517
UPDATE `trans_words` SET `content_loc7`='Stay back and forge more weapons?  Pah!  A Forgehammer has ne\'er been afraid of battle!  Who needs the safety of home to make weapons?  Besides - there is oodles of raw material out here. Those Dragonmaw weapons are worthless, but they can be smelted down to make actual weapons. Bring me 8 Dragonmaw weapons so me daughter and I can forge real weapons out of them.' WHERE `word_id` = 185869; -- locales_quest - details : entry=27814
UPDATE `trans_words` SET `content_loc7`='Stay back! Don\'t make me... Is it you?  By the Light!  It\'s you, $N!' WHERE `word_id` = 174278; -- locales_quest - offerrewardtext : entry=14406
UPDATE `trans_words` SET `content_loc7`='Stay where you are for just a moment... I am testing out a new combination of crystals...' WHERE `word_id` = 138641; -- locales_quest - offerrewardtext : entry=3941
UPDATE `trans_words` SET `content_loc7`='Stay where you are, champion. I have not yet decided what to do with you or your Earthen Ring.' WHERE `word_id` = 182223; -- locales_quest - details : entry=26752
UPDATE `trans_words` SET `content_loc7`='Stay your hand!  Please, I beg you!$B$BI\'m only here because of a girl. Her words were so sweet... but now I realize the madness behind them.$B$BTake this envelope. It has information that\'ll score you some points with your superiors.$B$BThe guards are distracted... I can make a run for it. Please. I don\'t want to die!' WHERE `word_id` = 177074; -- locales_quest - details : entry=25313
UPDATE `trans_words` SET `content_loc7`='Stayed Out of Harrison\'s Way' WHERE `word_id` = 184428; -- locales_quest - ObjectiveText1 : entry=27431
UPDATE `trans_words` SET `content_loc7`='Steal 10 pumpkins from the Solliden Farmstead in Tirisfal Glades.' WHERE `word_id` = 175870; -- locales_quest - objectives : entry=24975
