UPDATE `trans_words` SET `content_loc7`='Sylvanas will want to know about Thassarian\'s departure from Andorhal. You resolve to return to the Forsaken-held side of town.' WHERE `word_id` = 183449; -- locales_quest - details : entry=27090
UPDATE `trans_words` SET `content_loc7`='T\'chali has asked you to take the Bloodmaul Brutebane Keg and use it in an attempt to get 5 Bladespire Ogres drunk. If successful, return to T\'chali the Witch Doctor at Bloodmaul Ravine in the Blade\'s Edge Mountains.' WHERE `word_id` = 151416; -- locales_quest - objectives : entry=10545
UPDATE `trans_words` SET `content_loc7`='T\'chali is pleased that Korgaah and Grimnok Battleborn are pushing up daisies just like him.$B$BBut T\'chali\'s thirst for revenge is not quenched. There\'s one more thing that you must do!' WHERE `word_id` = 151405; -- locales_quest - offerrewardtext : entry=10543
UPDATE `trans_words` SET `content_loc7`='T\'chali the Witch Doctor has asked you to kill his chief tormentors, Grimnok Battleborn and Korgaah. After you have done so, return to him at Bloodmaul Ravine in the Blade\'s Edge Mountains.' WHERE `word_id` = 151404; -- locales_quest - objectives : entry=10543
