UPDATE `trans_words` SET `content_loc7`='Take it from me, $G lad:lass;, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.$B$BI need you to pilfer some o\' them weapons before they\'re used on us!' WHERE `word_id` = 191371; -- locales_quest - details : entry=29764
